INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('kitab-al-riyad', 'Islamic', 'Kitab al-Riyad', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('kitab-al-riyad', 'كتاب الرياض', 'ar', 'reality', '<p>This is a book of judgment. Its author, the Ismaili missionary Hamid al-Din Ahmad ibn Abd Allah al-Kirmani, known by the title Hujjat al-Iraqayn, did not compose it to lay out a doctrine of his own. He composed it to weigh, within a garden already planted, the work of two who came before him — each a reformer in his turn. The first is al-Nasafi, author of a book called al-Islah; the second is Abu Yaqub al-Sijistani, author of al-Nusra. Between these two the author takes his stand, measuring what each advanced and rendering a verdict.</p>', NULL, 'kitab-al-riyad/cover.png', 'kitab-al-riyad/book.pdf', '2026-08-29T20:17:47Z', '46129cd6f0dc8a11ac4bdab0739b9368abc93429');
