INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'the soul that forgets', 'pp. 78-102', '["Chapter Twenty-One of Part One", "The author of al-Nusra said", "One of the clearest signs of the deficiency of the Soul and the perfection of the First Intellect is that", "Abu Zakariyya said", "Chapter Twenty-Two of Part One", "The author of al-Nusrah said", "We say", "Chapter Twenty-Three of Part One"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'motion, stillness, and the bodiless intellect', 'pp. 103-112', '["The Second Chapter of Kitab al-Riyad", "Chapter One of Part Two", "The author of al-Islah said", "We say", "The author of al-Nusra said", "We say", "Chapter Two of Part Two", "The author of al-Islah said"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'light, darkness, and the matter below', 'pp. 113-120', '["The Third Chapter of the Book of Riyadh", "Chapter One", "The author of al-Islah said", "The author of al-Nusrah said", "He said", "This is what he said.", "We say", "Then we say"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'parts or traces?', 'pp. 121-128', '["Chapter Four of the Book of Riyadh", "On the judgment between *the hunters* — so the discussion concerning it, on the soul being parts and effects.", "Chapter One of Chapter Four", "The author of the Reform said", "The author of al-Nusrah said", "This statement is confused and contradictory in appearance, because he said", "We say", "Chapter Two of Chapter Four"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'the fruit of two worlds', 'pp. 129-136', '["Chapter Five of the Book of Riyad", "On the judgment between the two disputants — I speak of him — since human beings are the fruit of the physical world.", "Chapter One of Chapter Five", "The author of al-Islah said", "The author of al-Nusrah said", "But we would say", "We say", "Chapter Two of Chapter Five"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'body, form, and the two letters of ''be''', 'pp. 137-144', '["Chapter Six of the Book of al-Riyad", "In which he speaks of motion, stillness, hyle, and form.", "Chapter One of Chapter Six", "The author of al-Islah said", "The author of al-Nusrah said", "This is not the case of the soul and the body, where the measure between them is only the gentler and the denser.", "We say", "Chapter Two of Chapter Six"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'the small world', 'pp. 145-154', '["Chapter Seven of the Book of al-Riyad", "On the ruling between the two.", "I now speak of it in the sections that follow on the world.", "Section One of Chapter Seven", "The author of al-Islah said", "We say", "The author of al-Nusrah said", "The state of pairing is not only the state of sexual union; the state of pairing is also the state of acceptance."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'decree and destiny', 'pp. 155-166', '["Chapter Eight of the Book of Riyad", "On the Judgment between the Two Sages", "Chapter One of Section Eight", "The author of al-Islah said", "The author of al-Nusrah said", "We say", "Chapter Two of Section Eight", "Chapter Three of Section Eight"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'fleeing to god''s measure', 'pp. 166-177', '["Section Sixteen of Chapter Eight", "The author of al-Islah said", "The author of al-Nusrah said", "It is to multiply, be careful.", "We say", "Thy", "Chapter Seventeen of Chapter Eight", "Chapter Eighteen of Chapter Eight"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'did adam bring a law?', 'pp. 178-192', '["Chapter Nine of the Book of Riyadh", "On Ruling Between the Two", "Chapter One", "The author of al-Islah said", "Rather, we say", "The Book of Riyadh [12]", "The author of al-Nusrah said", "We say"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'the six gates of necessity', 'pp. 192-205', '["Chapter XIV of Title IX", "The author of al-Nusrah said", "We say", "We say", "Chapter XV of Title IX", "Then we say", "We say", "Chapter Sixteen of Title IX"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'cycles, prophets, and the ark', 'pp. 205-214', '["Chapter Twenty-Seven of Title IX", "The author of al-Islah said", "The first line is not obligatory until the second line appears, because the line", "The author of al-Nusrah said", "Concerning the chapter on the six ʿarḍas between the seven lines, and his inference from the lines", "Rather, the seven lines stand for the higher letters, since every Prophet wrote a letter", "Qā''ims save the cycle of their successors and their substitutes in the world. So six", "Adam — Noah — Abraham — Moses — Jesus — Muhammad — al-Qā''im."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'the creator of the thing and the no-thing', 'pp. 215-222', '["Chapter Ten of the Book of Riyadh", "Chapter One of Chapter Ten", "We say", "Chapter Two of Chapter Ten", "The author of al-Mahsul said", "We say", "Chapter Three of Title Ten", "Then we say"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('kitab-al-riyad', 'creativity is the creator', 'pp. 222-232', '["Chapter Eight of Title X", "The owner of the crop said", "We say", "Chapter Nine of Title Ten", "The owner of the crop said", "When the mind''s cause was the unity of the Almighty and the unity of eternity, the mind became eternal.", "Based on that, we say", "Chapter Ten of Chapter Ten"]');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'blurb', NULL, 'Kitab al-Riyad', 0, NULL, 'This is a book of judgment. Its author, the Ismaili missionary Hamid al-Din Ahmad ibn Abd Allah al-Kirmani, known by the title Hujjat al-Iraqayn, did not compose it to lay out a doctrine of his own. He composed it to weigh, within a garden already planted, the work of two who came before him — each a reformer in his turn. The first is al-Nasafi, author of a book called al-Islah; the second is Abu Yaqub al-Sijistani, author of al-Nusra. Between these two the author takes his stand, measuring what each advanced and rendering a verdict.', '', NULL, NULL, NULL, NULL, 'kitab al riyad', 'this is a book of judgment its author the ismaili missionary hamid al din ahmad ibn abd allah al kirmani known by the title hujjat al iraqayn did not compose it to lay out a doctrine of his own he composed it to weigh within a garden already planted the work of two who came before him each a reformer in his turn the first is al nasafi author of a book called al islah the second is abu yaqub al sijistani author of al nusra between these two the author takes his stand measuring what each advanced and rendering a verdict', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This is a book of judgment. Its author, the Ismaili missionary Hamid al-Din Ahmad ibn Abd Allah al-Kirmani (اَلْكِرْمَانِيّ), known by the title Hujjat al-Iraqayn (حُجَّةُ الْعِرَاقَيْن) — the Proof of the Two Iraqs — did not compose it to lay out a doctrine of his own. He composed it to weigh, within a garden already planted, the work of two who came before him. Between them the author takes his stand, measuring what each advanced and rendering a verdict on the rank of the soul beside the intellect, the parts that compose the human being, the human person as a small image of the whole, decree and destiny, the origin of the sacred law in Adam and Noah, and the oneness of God together with the act of creation. It is, then, a work of measured argument — a garden opened not to be planted anew, but to be judged.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'this is a book of judgment its author the ismaili missionary hamid al din ahmad ibn abd allah al kirmani الكرماني known by the title hujjat al iraqayn حجه العراقين the proof of the two iraqs did not compose it to lay out a doctrine of his own he composed it to weigh within a garden already planted the work of two who came before him between them the author takes his stand measuring what each advanced and rendering a verdict on the rank of the soul beside the intellect the parts that compose the human being the human person as a small image of the whole decree and destiny the origin of the sacred law in adam and noah and the oneness of god together with the act of creation it is then a work of measured argument a garden opened not to be planted anew but to be judged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The Islamic world at the close of the third century of the Hijra bore the unmistakable stamp of its sciences, philosophy, and literature — new currents and an unending theological argument that settled with no single party. Among the sects that contributed most generously to this ferment were the Ismailis, who did not wait to conclude their argument with other sects before turning inward to a dispute of an altogether new kind: a dispute among the very men who had summoned others to the Ismaili cause. In this there is clear evidence of an intellectual freedom that prevailed in their lives.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'the islamic world at the close of the third century of the hijra bore the unmistakable stamp of its sciences philosophy and literature new currents and an unending theological argument that settled with no single party among the sects that contributed most generously to this ferment were the ismailis who did not wait to conclude their argument with other sects before turning inward to a dispute of an altogether new kind a dispute among the very men who had summoned others to the ismaili cause in this there is clear evidence of an intellectual freedom that prevailed in their lives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 3, NULL, 'The dispute began with a book called al-Mahsul (The Harvest), put into circulation at the beginning of the fourth century AH (the tenth century AD) and attributed to the Syrian preacher Muhammad ibn Ahmad al-Nasafi (مُحَمَّدُ بْنُ أَحْمَدَ النَّسَفِيّ), who was credited with turning the Samanid state toward Ismailism and was put to death in 331 AH (942 AD), as recorded in Abd al-Qahir al-Baghdadi''s al-Farq bayn al-Firaq (The Difference Between the Sects). Strangely, al-Kirmani — who examined the whole affair in depth — never once names al-Nasafi as al-Mahsuls author, directing his discussion instead at Abu Hatim al-Razi and Abu Yaqub al-Sijistani; it may be that the attribution to al-Nasafi is itself mistaken.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'the dispute began with a book called al mahsul the harvest put into circulation at the beginning of the fourth century ah the tenth century ad and attributed to the syrian preacher muhammad ibn ahmad al nasafi محمد بن احمد النسفي who was credited with turning the samanid state toward ismailism and was put to death in 331 ah 942 ad as recorded in abd al qahir al baghdadis al farq bayn al firaq the difference between the sects strangely al kirmani who examined the whole affair in depth never once names al nasafi as al mahsuls author directing his discussion instead at abu hatim al razi and abu yaqub al sijistani it may be that the attribution to al nasafi is itself mistaken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 4, NULL, 'Whatever the truth of that, the acclaim al-Mahsul won among Ismaili scholars spurred Abu Hatim al-Razi, the foremost preacher of northwestern Persia, to compose a reply, al-Islah (The Correction). Al-Razi''s opinions in turn provoked Abu Yaqub al-Sijistani, who judged them contrary to truth and first principles and answered with al-Nusra (The Defense) — among his earliest works, upholding al-Mahsul and attacking al-Razi without mercy. Not long afterward al-Kirmani surveyed the whole controversy and composed al-Riyad (The Gardens), a judgment between the two reformers — that is, between the authors of al-Islah and al-Nusra — appraising all three books with rigorous scholarly criticism and measuring them against the Law of the Guiding Mission (قَانُونُ الدَّعْوَةِ الْهَادِيَةِ): the official philosophical and doctrinal positions of the Fatimid court. Of the four books in this chain, only two survive: al-Islah by al-Razi and al-Riyad by al-Kirmani. Al-Mahsul and al-Nusra have been lost.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'whatever the truth of that the acclaim al mahsul won among ismaili scholars spurred abu hatim al razi the foremost preacher of northwestern persia to compose a reply al islah the correction al razis opinions in turn provoked abu yaqub al sijistani who judged them contrary to truth and first principles and answered with al nusra the defense among his earliest works upholding al mahsul and attacking al razi without mercy not long afterward al kirmani surveyed the whole controversy and composed al riyad the gardens a judgment between the two reformers that is between the authors of al islah and al nusra appraising all three books with rigorous scholarly criticism and measuring them against the law of the guiding mission قانون الدعوه الهاديه the official philosophical and doctrinal positions of the fatimid court of the four books in this chain only two survive al islah by al razi and al riyad by al kirmani al mahsul and al nusra have been lost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 5, NULL, 'Al-Riyad stands among the important works giving voice to Ismaili philosophy in the fourth century of the Hijra. The present editor obtained two manuscript copies — one from India, one from Tehran — and was charged with editing the book, explaining it, and writing its footnotes and commentary. Before taking up its arguments in detail, a brief account is owed of the lives of the three philosophers who took part in the dispute: al-Razi, al-Sijistani, and al-Kirmani.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al riyad stands among the important works giving voice to ismaili philosophy in the fourth century of the hijra the present editor obtained two manuscript copies one from india one from tehran and was charged with editing the book explaining it and writing its footnotes and commentary before taking up its arguments in detail a brief account is owed of the lives of the three philosophers who took part in the dispute al razi al sijistani and al kirmani', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 7, NULL, 'Al-Razi. He is Abu Hatim Ahmad ibn Hamdan al-Laythi al-Warsanani al-Razi (أَبُو حَاتِم أَحْمَد بْن حَمْدَان الرَّازِي), whom the Ismailis name in reverence "our master Abu Hatim." A preacher first in Rayy and later resident in Baghdad, his birth date is unknown; his mission work fell in the imamate of Muhammad al-Mahdi Billah (Ubayd Allah), founder of the Fatimid state in the Maghrib. Renowned for his eloquence, he won over al-Marwazi, the Sunni prince of Rayy, and other regional princes, becoming a pillar of both politics and religion and a leading figure of the Islamic scholarly renaissance of his age. The orientalist Paul Kraus judged him a leading Ismaili preacher whose political weight in Tabaristan, Daylam, Rayy, and Isfahan won the allegiance of men such as Asfar ibn Shirawayh and the commander Mardawij. Persecuted by enemies in Daylam, he was driven into hiding and died in 322 AH, reportedly aged sixty-two, during the reign of the Fatimid al-Qaim.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al razi he is abu hatim ahmad ibn hamdan al laythi al warsanani al razi ابو حاتم احمد بن حمدان الرازي whom the ismailis name in reverence our master abu hatim a preacher first in rayy and later resident in baghdad his birth date is unknown his mission work fell in the imamate of muhammad al mahdi billah ubayd allah founder of the fatimid state in the maghrib renowned for his eloquence he won over al marwazi the sunni prince of rayy and other regional princes becoming a pillar of both politics and religion and a leading figure of the islamic scholarly renaissance of his age the orientalist paul kraus judged him a leading ismaili preacher whose political weight in tabaristan daylam rayy and isfahan won the allegiance of men such as asfar ibn shirawayh and the commander mardawij persecuted by enemies in daylam he was driven into hiding and died in 322 ah reportedly aged sixty two during the reign of the fatimid al qaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 8, NULL, 'Al-Razi was a contemporary and fierce public disputant of the physician-philosopher Abu Bakr Muhammad ibn Zakariya al-Razi, who broke with much of Aristotle, denied any reconciliation of philosophy and religion, and held philosophy the only road to reform. Abu Hatim recorded their debates in Alam al-Nubuwwa, naming his opponent only "the atheist" — though the evidence identifies him as Abu Bakr. Al-Kirmani''s own al-Aqwal al-Dhahabiyya records their disputations over prophethood and the Law in Rayy, before Mardawij, in which Abu Hatim is said to have humbled his rival. Al-Razi''s most important work is al-Zina, a twelve-hundred-page study of Arabic letters, derivations, and vocabulary foundational to Islamic terminology, dedicated to the Fatimid imam who succeeded Muhammad al-Mahdi Billah. To him belong also Alam al-Nubuwwa, al-Islah, al-Jami, and others.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al razi was a contemporary and fierce public disputant of the physician philosopher abu bakr muhammad ibn zakariya al razi who broke with much of aristotle denied any reconciliation of philosophy and religion and held philosophy the only road to reform abu hatim recorded their debates in alam al nubuwwa naming his opponent only the atheist though the evidence identifies him as abu bakr al kirmanis own al aqwal al dhahabiyya records their disputations over prophethood and the law in rayy before mardawij in which abu hatim is said to have humbled his rival al razis most important work is al zina a twelve hundred page study of arabic letters derivations and vocabulary foundational to islamic terminology dedicated to the fatimid imam who succeeded muhammad al mahdi billah to him belong also alam al nubuwwa al islah al jami and others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 9, NULL, 'Al-Sijistani. Abu Yaqub Ishaq al-Sijistani (أَبُو يَعْقُوب إِسْحَاق السِّجِسْتَانِي), also called al-Sijzi, ranks among the foremost builders of Ismaili philosophical and cosmological doctrine on firm intellectual foundations. He sacrificed much to spread that teaching, and late in life was accused of unbelief by conservative society and killed for his faith. His teaching shaped his disciple al-Kirmani directly, which alone places him among the first rank of Muslim philosophers. He lived during the public flourishing of the Fatimid state, yet in a land hostile to his belief, so that he practiced التَّقِيَّة (dissimulation) and his biography survives only in outline — as is true, too, of al-Nasafi, of al-Razi, and even of al-Kirmani himself, whose biography al-Muayyad fil-Din Hibatallah al-Shirazi (friend and disputant of the poet Abu al-Ala al-Maarri) wrote in his own hand; the lives of most senior preachers of the mission are lost in similar obscurity.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al sijistani abu yaqub ishaq al sijistani ابو يعقوب اسحاق السجستاني also called al sijzi ranks among the foremost builders of ismaili philosophical and cosmological doctrine on firm intellectual foundations he sacrificed much to spread that teaching and late in life was accused of unbelief by conservative society and killed for his faith his teaching shaped his disciple al kirmani directly which alone places him among the first rank of muslim philosophers he lived during the public flourishing of the fatimid state yet in a land hostile to his belief so that he practiced التقيه dissimulation and his biography survives only in outline as is true too of al nasafi of al razi and even of al kirmani himself whose biography al muayyad fil din hibatallah al shirazi friend and disputant of the poet abu al ala al maarri wrote in his own hand the lives of most senior preachers of the mission are lost in similar obscurity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 10, NULL, 'Al-Sijistani is traced to Sijistan in southern Khurasan, either to a Persian family said to descend from the hero Rustam, or — by another account — to Iraqi ancestry through a grandfather from Kufa. His death is sometimes placed at 331 AH, though this cannot be reconciled with his having taught al-Kirmani, who lived until 411 AH; his own book al-Iftikhar, which he says he composed in 360 AH and which al-Kirmani cites in al-Riyad, places him as an active preacher in Bukhara under the Fatimid imam al-Muizz li-Din Allah, a contemporary of the preacher Jafar ibn Mansur al-Yamani and the chief judge al-Numan ibn Muhammad ibn Hayyun al-Maghribi al-Tamimi. He left more than thirty works, among the deepest ever written in Ismaili philosophy: chiefly Ithbat al-Nubuwwat, Kashf al-Mahjub, Tuhfat al-Mustajibin, and al-Yanabi — divided into forty "springs," each carrying the interpretation of one of the forty limits of the mission''s supreme council, written for its most advanced preachers. Nasir-i Khusraw''s Zad al-Musafirin lists further titles: The Foundations of the Dawa, The Interpretation of the Laws, The Iris of Blessings (or of Survival), The Brilliant Message, Kitab al-Iftikhar, The Scales (in nineteen scales), The Ladder of Salvation, al-Nusra, The Hooks, Amusements of Sorrows, Secrets of the Return, Sermons on Ethics, The Stranger on the Meaning of the Elixir, Sociable of Hearts, Composition of Spirits, Security from Confusion, Closets of Evidence, The Proof, and others.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al sijistani is traced to sijistan in southern khurasan either to a persian family said to descend from the hero rustam or by another account to iraqi ancestry through a grandfather from kufa his death is sometimes placed at 331 ah though this cannot be reconciled with his having taught al kirmani who lived until 411 ah his own book al iftikhar which he says he composed in 360 ah and which al kirmani cites in al riyad places him as an active preacher in bukhara under the fatimid imam al muizz li din allah a contemporary of the preacher jafar ibn mansur al yamani and the chief judge al numan ibn muhammad ibn hayyun al maghribi al tamimi he left more than thirty works among the deepest ever written in ismaili philosophy chiefly ithbat al nubuwwat kashf al mahjub tuhfat al mustajibin and al yanabi divided into forty springs each carrying the interpretation of one of the forty limits of the missions supreme council written for its most advanced preachers nasir i khusraws zad al musafirin lists further titles the foundations of the dawa the interpretation of the laws the iris of blessings or of survival the brilliant message kitab al iftikhar the scales in nineteen scales the ladder of salvation al nusra the hooks amusements of sorrows secrets of the return sermons on ethics the stranger on the meaning of the elixir sociable of hearts composition of spirits security from confusion closets of evidence the proof and others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 11, NULL, 'Al-Sijistani''s theology holds God an Ancient, eternal Creator, utterly beyond sense, sight, genus, analogy, likeness, opposite, or equal — knowable only through His creation and works, and by name only through His prophets, since the intellect cannot set the created beside its Originator. He has, properly, neither name nor attribute, for these belong to created things, and no language can express Him; He is the "first Number," as the Intellect is the origin of existents and the Articulator (the prophetic voice) the origin of the religious world. His existence is proven from the dependence of all existents on one another and, ultimately, on Him. From this follows al-Sijistani''s ordering of creation: the first act brings forth the Intellect — called also the Pen, the Throne, the First, prime matter (اَلْهَيُولَى), and the Sun — unique among existents in that its act precedes its power. From the Intellect wells the second creation, the Soul — called the Tablet, the King, the Follower, Destiny, and the Image, its light borrowed from the Intellect as the moon''s from the sun. Together, Intellect and Soul are named the Two Principles (الْأَصْلَان).', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al sijistanis theology holds god an ancient eternal creator utterly beyond sense sight genus analogy likeness opposite or equal knowable only through his creation and works and by name only through his prophets since the intellect cannot set the created beside its originator he has properly neither name nor attribute for these belong to created things and no language can express him he is the first number as the intellect is the origin of existents and the articulator the prophetic voice the origin of the religious world his existence is proven from the dependence of all existents on one another and ultimately on him from this follows al sijistanis ordering of creation the first act brings forth the intellect called also the pen the throne the first prime matter الهيولي and the sun unique among existents in that its act precedes its power from the intellect wells the second creation the soul called the tablet the king the follower destiny and the image its light borrowed from the intellect as the moons from the sun together intellect and soul are named the two principles الاصلان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 12, NULL, 'Al-Kirmani. An extraordinary figure whose own life is likewise enveloped in obscurity, al-Kirmani is reckoned by Islamic philosophers the greatest scholar the Ismaili school produced. The Yemeni historian Idris Imad al-Din called him', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al kirmani an extraordinary figure whose own life is likewise enveloped in obscurity al kirmani is reckoned by islamic philosophers the greatest scholar the ismaili school produced the yemeni historian idris imad al din called him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 13, NULL, 'Saying"هُوَ أَسَاسُ الدَّعْوَةِ الَّتِي عَلَيْهِ عِمَادُهَا وَبِهِ عَلَا وَاسْتَقَامَ مَنَارُهَا وَبِهِ اسْتَبَانَتِ الْمُشْكِلَاتُ وَانْفَرَجَتِ الْمُعْضِلَاتُ""the foundation of the دَعْوَة upon which it rests and by which it is raised up; through him its beacon was set straight, and by him problems were identified and dilemmas resolved,"', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad introduction to the book', 'saying هو اساس الدعوه التي عليه عمادها وبه علا واستقام منارها وبه استبانت المشكلات وانفرجت المعضلات the foundation of the دعوه upon which it rests and by which it is raised up through him its beacon was set straight and by him problems were identified and dilemmas resolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 14, NULL, 'and the Syrian preacher Nur al-Din Ahmad wrote that', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'and the syrian preacher nur al din ahmad wrote that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 15, NULL, 'Saying"لو ان الدعوة الاسماعيلية لم تنتج غير الكرماني لكفاها فخراً ومجداً ولكان ذلك كافياً""if the Ismaili dawa had produced nothing but al-Kirmani, that alone would have been ample pride and glory."', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad introduction to the book', 'saying لو ان الدعوه الاسماعيليه لم تنتج غير الكرماني لكفاها فخرا ومجدا ولكان ذلك كافيا if the ismaili dawa had produced nothing but al kirmani that alone would have been ample pride and glory', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 16, NULL, 'His stature came into full view under the Fatimid Caliph al-Hakim bi-Amr Allah. As Hujjat al-Iraqayn he oversaw the dawa''s affairs across Persia and Iraq; in Cairo he held the rank of حُجَّة, one of twelve overseeing the mission, and was later appointed head of Dar al-Hikma (the House of Wisdom) — arguably the first university in the world. He traveled to Cairo in 408 AH at the summons of al-Sadiq al-Mamun, then the Fatimid state''s chief preacher, at a moment of intensifying religious conflict and doctrinal deviation. There he lectured and wrote prolifically, most famously the Preacher''s Message, refuting al-Hasan al-Farghani''s claim that al-Hakim was himself divine, and the epistles Good Tidings and Lamps, which proved the Imamate a cosmic necessity through arguments drawing on Hebrew, Syriac, and Persian scripture and on Platonic thought.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'his stature came into full view under the fatimid caliph al hakim bi amr allah as hujjat al iraqayn he oversaw the dawas affairs across persia and iraq in cairo he held the rank of حجه one of twelve overseeing the mission and was later appointed head of dar al hikma the house of wisdom arguably the first university in the world he traveled to cairo in 408 ah at the summons of al sadiq al mamun then the fatimid states chief preacher at a moment of intensifying religious conflict and doctrinal deviation there he lectured and wrote prolifically most famously the preachers message refuting al hasan al farghanis claim that al hakim was himself divine and the epistles good tidings and lamps which proved the imamate a cosmic necessity through arguments drawing on hebrew syriac and persian scripture and on platonic thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 17, NULL, 'Al-Kirmani deserves to be read not merely as an Ismaili preacher but as a philosopher of world rank, who took the theory of the unity of being shared by al-Farabi ("the Second Teacher") and Ibn Sina ("the Chief Sheikh") and expanded it well beyond the curriculum expected of an Ismaili preacher of his age. His doctrine of continuous creation — that existents persist despite the apparent contradiction and mutual erasure among them, none lost, all preserved in being — closely anticipates al-Farabi''s and Ibn Sina''s own formulations of the same principle, and Descartes''s much later claim that God''s act of preserving the world and His act of creating it are one and the same. Al-Kirmani absorbed the Muslim philosophers before him yet stamped their material with his own originality, making him, in the editor''s judgment, a precursor of both modern European philosophy and Oriental renewal — his output properly Islamic philosophy of the first order, not merely a sectarian achievement.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al kirmani deserves to be read not merely as an ismaili preacher but as a philosopher of world rank who took the theory of the unity of being shared by al farabi the second teacher and ibn sina the chief sheikh and expanded it well beyond the curriculum expected of an ismaili preacher of his age his doctrine of continuous creation that existents persist despite the apparent contradiction and mutual erasure among them none lost all preserved in being closely anticipates al farabis and ibn sinas own formulations of the same principle and descartess much later claim that gods act of preserving the world and his act of creating it are one and the same al kirmani absorbed the muslim philosophers before him yet stamped their material with his own originality making him in the editors judgment a precursor of both modern european philosophy and oriental renewal his output properly islamic philosophy of the first order not merely a sectarian achievement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 18, NULL, 'Working within Neoplatonism, al-Kirmani argued for Prophethood and the Imamate on both philosophical and religious grounds, holding that ordinary believers follow the outward Shariah while the deeper philosophical interpretation of the hudud (limits, الحدود) is reserved for the qualified elite — a position visible in The Illuminating Message, The Lamps in Proving the Imamate, Alerting the Guide and the Guided, and Rest of the Mind (رَاحَة الْعَقْل). He contributed original doctrine on the call to existence, the negation of essence (al-aysiyya) and substance (al-laysiyya), the absolute negation of divine attributes, tawhid, the two principles of origination, emanation, and the relative priority of Imamate and Prophethood — and in Rest of the Mind set new foundations for the doctrine of the Imamate specifically. His negative theology — that no attribute attaches to God, that He is neither a body nor in one, neither senses nor rationalizes Himself, has no form, opposite, or likeness, and cannot be captured in language — echoes the Mutazila and the mutakallimun and finds an echo in Ibn Rushd, while his proof of God''s existence resembles Descartes''s; his synthesis draws on Plato, Aristotle, al-Kindi, al-Farabi, and Ibn Sina. Against the charge — pressed by al-Baqillani, al-Baghdadi, and al-Ghazali — that the Ismailis'' denial of divine attributes amounted to voiding God altogether (al-tatil), al-Kirmani answered that their negation touches only the attributes, never God''s own identity: the negative particle "لا" is directed at what is predicated of Him, not at "هُو" — Him. Distinctively, Rest of the Mind is not divided into ordinary books and chapters but organized as a walled city of seven walls, six pierced by seven gates each and the seventh, last wall by fourteen.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'working within neoplatonism al kirmani argued for prophethood and the imamate on both philosophical and religious grounds holding that ordinary believers follow the outward shariah while the deeper philosophical interpretation of the hudud limits الحدود is reserved for the qualified elite a position visible in the illuminating message the lamps in proving the imamate alerting the guide and the guided and rest of the mind راحه العقل he contributed original doctrine on the call to existence the negation of essence al aysiyya and substance al laysiyya the absolute negation of divine attributes tawhid the two principles of origination emanation and the relative priority of imamate and prophethood and in rest of the mind set new foundations for the doctrine of the imamate specifically his negative theology that no attribute attaches to god that he is neither a body nor in one neither senses nor rationalizes himself has no form opposite or likeness and cannot be captured in language echoes the mutazila and the mutakallimun and finds an echo in ibn rushd while his proof of gods existence resembles descartess his synthesis draws on plato aristotle al kindi al farabi and ibn sina against the charge pressed by al baqillani al baghdadi and al ghazali that the ismailis denial of divine attributes amounted to voiding god altogether al tatil al kirmani answered that their negation touches only the attributes never gods own identity the negative particle لا is directed at what is predicated of him not at هو him distinctively rest of the mind is not divided into ordinary books and chapters but organized as a walled city of seven walls six pierced by seven gates each and the seventh last wall by fourteen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 19, NULL, 'Among al-Kirmani''s works, beyond those already named, are The Divine Treatise, The Treatise of the Systems, The Treatise of Light, The Illuminating Treatise, The Necessary Treatise, The Guiding Treatise, The Preacher''s Treatise, The Sufficient Treatise, Wrists of the Guide, The Golden Sayings, Separating the Discourse and Distinguishing the Manifest Truth from Doubt, The Treatise of the Returner, The Treatise of the Index, Quantities and Facts, The Treatise on Tawhid in the Promised Land, The Crown of Intellects, The Balance of the Mind, The Book of Criticism and Obligation, Psychological Adequacy, The Book of Scales, The Baghdadi and Basran Sessions, al-Shaari''s Treatise on the Elite, and The Treatise of the Week of the Role of the Cover. His writings remain, in the editor''s judgment, of first importance to the history of Islamic philosophy and Oriental studies.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'among al kirmanis works beyond those already named are the divine treatise the treatise of the systems the treatise of light the illuminating treatise the necessary treatise the guiding treatise the preachers treatise the sufficient treatise wrists of the guide the golden sayings separating the discourse and distinguishing the manifest truth from doubt the treatise of the returner the treatise of the index quantities and facts the treatise on tawhid in the promised land the crown of intellects the balance of the mind the book of criticism and obligation psychological adequacy the book of scales the baghdadi and basran sessions al shaaris treatise on the elite and the treatise of the week of the role of the cover his writings remain in the editors judgment of first importance to the history of islamic philosophy and oriental studies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 21, NULL, 'Al-Kirmani opens the book itself in his own voice, with the Basmala —', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'al kirmani opens the book itself in his own voice with the basmala', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'verse', 'introduction to the book', 'Introduction to the Book', 22, NULL, 'Sayingبِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ', '', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ', 'Saying', 1, 1, 'kitab al riyad introduction to the book', 'sayingبسم الله الرحمن الرحيم', 'بسم الله الرحمن الرحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 23, NULL, '— and an extended doxology: praise of Allah, Creator of all things, whose decree is firm and unchanging, and against whom none who likens Him to His creation can but go astray; the bearing of witness that there is no god but Allah and that Muhammad is His Messenger, sent at a time when idols were worshipped in Allah''s sanctuary and the upright الْحَنِيْفِي religion lay low, who overthrew the idols, replaced the houses of fire with the Sacred House, turned worship from the crosses toward the Corner (الرُّكْن) and the Station (الْمَقَام), and brought the people to "the most trustworthy handhold" (اَلْعُرْوَةُ الْوُثْقَى) — closing this first blessing with the Quranic verse on', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'and an extended doxology praise of allah creator of all things whose decree is firm and unchanging and against whom none who likens him to his creation can but go astray the bearing of witness that there is no god but allah and that muhammad is his messenger sent at a time when idols were worshipped in allahs sanctuary and the upright الحنيفي religion lay low who overthrew the idols replaced the houses of fire with the sacred house turned worship from the crosses toward the corner الركن and the station المقام and brought the people to the most trustworthy handhold العروه الوثقي closing this first blessing with the quranic verse on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 24, NULL, 'Sayingيَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ ، إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ', '', 'يَوْمَ لَا يَنْفَعُ مَالٌ وَلَا بَنُونَ ، إِلَّا مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ', 'Saying', NULL, NULL, 'kitab al riyad introduction to the book', 'sayingيوم لا ينفع مال ولا بنون الا من اتي الله بقلب سليم', 'يوم لا ينفع مال ولا بنون الا من اتي الله بقلب سليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 25, NULL, '"a day on which neither wealth nor children will be of any use, except for him who comes to Allah with a sound heart." He then invokes a blessing upon Ali ibn Abi Talib, Commander of the Believers and Axis of the Religion, and upon the Imams descended from him — the family of Taha and Yasin — by whose guidance and intercession perfection is reached.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'a day on which neither wealth nor children will be of any use except for him who comes to allah with a sound heart he then invokes a blessing upon ali ibn abi talib commander of the believers and axis of the religion and upon the imams descended from him the family of taha and yasin by whose guidance and intercession perfection is reached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 26, NULL, 'To proceed, he writes: the most essential task for one who affirms the divine unity is to reach, and to help others reach, a settled certainty in tawhid and in the knowledge of the hudud (limits) — since confusion there unsettles belief itself. He explains that Abu Hatim al-Razi had undertaken, in al-Islah, to correct what he held corrupted in al-Mahsul, and that Abu Yaqub al-Sijzi had come, in al-Nusra, to that book''s defense. This was, al-Kirmani judged, no permissible disagreement over secondary matters (فروع) but touched the foundations (أصول) themselves. He found al-Sijzi truthful in some of his aims yet prejudiced against Abu Hatim in others, and found both men''s arguments, in places, poorly ordered; he further found that al-Mahsul itself, in its chapter on tawhid concerning the First Intellect, contained errors that Abu Hatim was better placed to correct than the long secondary matter with which he had instead lengthened his own book — leaving the people of the Guiding دَعْوَة unsettled in both tawhid and the knowledge of the limits whenever they met a point of difference.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'to proceed he writes the most essential task for one who affirms the divine unity is to reach and to help others reach a settled certainty in tawhid and in the knowledge of the hudud limits since confusion there unsettles belief itself he explains that abu hatim al razi had undertaken in al islah to correct what he held corrupted in al mahsul and that abu yaqub al sijzi had come in al nusra to that books defense this was al kirmani judged no permissible disagreement over secondary matters فروع but touched the foundations اصول themselves he found al sijzi truthful in some of his aims yet prejudiced against abu hatim in others and found both mens arguments in places poorly ordered he further found that al mahsul itself in its chapter on tawhid concerning the first intellect contained errors that abu hatim was better placed to correct than the long secondary matter with which he had instead lengthened his own book leaving the people of the guiding دعوه unsettled in both tawhid and the knowledge of the limits whenever they met a point of difference', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 27, NULL, 'His method, he states, was therefore threefold: to set down each side''s own words, from al-Islah and al-Nusra, in their own text; to show what necessarily follows from each and distinguish the truthful from the prejudiced, so that a believer might judge rightly; and to correct what al-Mahsul left wrong among the foundations, where disagreement is not permitted. He named the resulting book al-Riyad — "The Gardens" — a ruling between the author of al-Islah and the author of al-Nusra, and a correction of what al-Mahsul left unaddressed, undertaken through the blessings of the أَوْلِيَاء of Allah. He named it for gardens because it offers, like a garden, greenery pleasing to the eye and fruit that comes readily to the hand — asking Allah''s help, and acknowledging that though he sought to be kept from error, he does not claim to be free of it.', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'his method he states was therefore threefold to set down each sides own words from al islah and al nusra in their own text to show what necessarily follows from each and distinguish the truthful from the prejudiced so that a believer might judge rightly and to correct what al mahsul left wrong among the foundations where disagreement is not permitted he named the resulting book al riyad the gardens a ruling between the author of al islah and the author of al nusra and a correction of what al mahsul left unaddressed undertaken through the blessings of the اولياء of allah he named it for gardens because it offers like a garden greenery pleasing to the eye and fruit that comes readily to the hand asking allahs help and acknowledging that though he sought to be kept from error he does not claim to be free of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 28, NULL, 'The book comprises ten chapters, containing in total one hundred and fifty-seven sub-chapters. As al-Kirmani closes:', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'the book comprises ten chapters containing in total one hundred and fifty seven sub chapters as al kirmani closes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 29, NULL, 'Sayingوَهُوَ حَسْبُنَا وَنِعْمَ الْوَكِيلُ', '', 'وَهُوَ حَسْبُنَا وَنِعْمَ الْوَكِيلُ', 'Saying', NULL, NULL, 'kitab al riyad introduction to the book', 'sayingوهو حسبنا ونعم الوكيل', 'وهو حسبنا ونعم الوكيل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'introduction to the book', 'Introduction to the Book', 30, NULL, '"He is sufficient for us, and the best Trustee."', '', NULL, NULL, NULL, NULL, 'kitab al riyad introduction to the book', 'he is sufficient for us and the best trustee', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 0, NULL, 'This is the first chapter, from the book al-Riyad, concerning the ruling between the two disputants, in the chapter on what was discussed regarding the soul, which is the first emanation.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'this is the first chapter from the book al riyad concerning the ruling between the two disputants in the chapter on what was discussed regarding the soul which is the first emanation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 2, NULL, 'The author of al-Islah held that the soul is complete in itself, having been emitted from the First Intellect complete. It is a complete emanation from what is complete, for the Intellect is perfection.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al islah held that the soul is complete in itself having been emitted from the first intellect complete it is a complete emanation from what is complete for the intellect is perfection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 3, NULL, 'The author of al-Nusra replied in refutation: the author of al-Islah does not recognize that perfection is better and more complete than the perfect. Perfection is an attribute, while the perfect is what is described. Perfection is what is borne, while the perfect is the bearer. What is described — the bearer — is better and more complete than the attribute and than the borne. For the perfect is described by perfection and bears it, while perfection is merely the attribute of the perfect, predicated upon it. This is what they say.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra replied in refutation the author of al islah does not recognize that perfection is better and more complete than the perfect perfection is an attribute while the perfect is what is described perfection is what is borne while the perfect is the bearer what is described the bearer is better and more complete than the attribute and than the borne for the perfect is described by perfection and bears it while perfection is merely the attribute of the perfect predicated upon it this is what they say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 4, NULL, 'We say: when the author of al-Islah says that the soul is complete because it is emitted from perfection, he does not mean that perfection is an attribute or is not one, nor that the perfect is described or is not. What he means is that perfection stands as a cause from which the existence of the effect arises. He saw that perfection is the cause of the perfect and precedes it in rank, for without perfection the perfect would not exist. The proof is that if we remove perfection in the imagination, the perfect is removed with it — just as with the source-forms from which the past act, the future, the agent, and the object are all derived: remove those source-forms, and whatever is derived from them by conjugation is removed along with them. He therefore treated the First Intellect — first in existence, and the source from which all existents came to be — as the cause, and said: it is perfection. He treated the emanating soul as the effect, and said: it is the perfect. Since this was the author of al-Islahs intention, his statement that the First Intellect is perfection is true. And since it is true, what the author of al-Nusra said in this manner was an overreach against the author of al-Islah.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say when the author of al islah says that the soul is complete because it is emitted from perfection he does not mean that perfection is an attribute or is not one nor that the perfect is described or is not what he means is that perfection stands as a cause from which the existence of the effect arises he saw that perfection is the cause of the perfect and precedes it in rank for without perfection the perfect would not exist the proof is that if we remove perfection in the imagination the perfect is removed with it just as with the source forms from which the past act the future the agent and the object are all derived remove those source forms and whatever is derived from them by conjugation is removed along with them he therefore treated the first intellect first in existence and the source from which all existents came to be as the cause and said it is perfection he treated the emanating soul as the effect and said it is the perfect since this was the author of al islahs intention his statement that the first intellect is perfection is true and since it is true what the author of al nusra said in this manner was an overreach against the author of al islah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 6, NULL, 'The author of al-Nusra holds that the perfect is better than perfection. Yet the discourse here — about perfection and the perfect — concerns the First Principle, which is the First Effect and the First Emanation, not any other thing. His claim therefore entails that nobility belongs to the effect and not to its cause. The proof: the perfect is perfect only by means of perfection, and without perfection it would not be perfect. Whatever a thing''s being depends on is its cause. Since the perfect''s existence is by perfection, perfection is the cause of the perfect, and the perfect is the effect of perfection. If the perfect is the effect of perfection, and the author of al-Nusra assigns nobility and merit to the perfect over perfection, then by that assignment he has made it necessary that the effect be nobler than its cause — and that is impossible. For whatever comes to exist through the existence of something, such that when that something is removed it ceases to exist, is below that something in nobility and precedence. And since that is impossible, the author of al-Nusra in what he brought forward was overreaching against the author of al-Islah.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra holds that the perfect is better than perfection yet the discourse here about perfection and the perfect concerns the first principle which is the first effect and the first emanation not any other thing his claim therefore entails that nobility belongs to the effect and not to its cause the proof the perfect is perfect only by means of perfection and without perfection it would not be perfect whatever a things being depends on is its cause since the perfects existence is by perfection perfection is the cause of the perfect and the perfect is the effect of perfection if the perfect is the effect of perfection and the author of al nusra assigns nobility and merit to the perfect over perfection then by that assignment he has made it necessary that the effect be nobler than its cause and that is impossible for whatever comes to exist through the existence of something such that when that something is removed it ceases to exist is below that something in nobility and precedence and since that is impossible the author of al nusra in what he brought forward was overreaching against the author of al islah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 8, NULL, 'The author of al-Nusra said, secondly: perfection is an attribute and the perfect is what is described; perfection is what is borne and the perfect is the bearer. He offered this as proof of his claim that the perfect is nobler than perfection, and that the bearer is nobler than the borne.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra said secondly perfection is an attribute and the perfect is what is described perfection is what is borne and the perfect is the bearer he offered this as proof of his claim that the perfect is nobler than perfection and that the bearer is nobler than the borne', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 9, NULL, 'We say: this does not hold without qualification. From the side of existing beings and the second emanation, we find instances in which what is borne is nobler than its bearer. The nutritive power is the proximate cause of the existence of the growth power and is its bearer, while the growth power is a form borne within it and its completion — and the growth power is nobler than the nutritive. The growth power is the proximate cause of the existence of the sensitive power and is its bearer, while the sensitive power is a form borne within it and its completion — and the sensitive is nobler than it. The sensitive power is the proximate cause of the existence of the speaking power and is its bearer, while the speaking power is a form borne within it and its completion. The nobility of the one is not like the nobility of the other.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say this does not hold without qualification from the side of existing beings and the second emanation we find instances in which what is borne is nobler than its bearer the nutritive power is the proximate cause of the existence of the growth power and is its bearer while the growth power is a form borne within it and its completion and the growth power is nobler than the nutritive the growth power is the proximate cause of the existence of the sensitive power and is its bearer while the sensitive power is a form borne within it and its completion and the sensitive is nobler than it the sensitive power is the proximate cause of the existence of the speaking power and is its bearer while the speaking power is a form borne within it and its completion the nobility of the one is not like the nobility of the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 10, NULL, 'Moreover, from the side of origination and the first emanation, it is impossible that the First Intellect be what is borne and the Second Intellect emanating from it be the bearer, or that the perfect — which is the First Intellect — be an attribute of the perfect that is the Second Intellect. This being so, the author of al-Nusras inference in his refutation was an overreach against the author of al-Islah. The meanings of his statement would hold true only if applied to natural things, which are far removed from what the author of al-Islah speaks of, namely the originative and emanative principles.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'moreover from the side of origination and the first emanation it is impossible that the first intellect be what is borne and the second intellect emanating from it be the bearer or that the perfect which is the first intellect be an attribute of the perfect that is the second intellect this being so the author of al nusras inference in his refutation was an overreach against the author of al islah the meanings of his statement would hold true only if applied to natural things which are far removed from what the author of al islah speaks of namely the originative and emanative principles', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 11, NULL, 'The statement of the author of al-Islah is correct with regard to the world of origination and emanation. The statement of the author of al-Nusra — though the author of al-Islah erred with respect to it — is correct with regard to the world of bodies and their accidents.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the statement of the author of al islah is correct with regard to the world of origination and emanation the statement of the author of al nusra though the author of al islah erred with respect to it is correct with regard to the world of bodies and their accidents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 13, NULL, 'We say, reflecting on this: perfection is a name that applies to the First Thing, which is the First Cause; and it is also the First Perfect, which is the First Effect. Its perfection comes from the relation of its existence to that from which its existence came, and its perfection comes from its relation to that upon which its essence rests — and this is analogous to origination and the Originator in their proper order. Origination is not something other than the Originator; it is that by which the Originator is itself. What, then, is it? It is a single essence: considered in relation to that from which its existence came, it is origination; considered in relation to that upon which its essence rests, bearing the mark of temporal occurrence, it is originated. Thus the First Intellect is perfection, and it is also the perfect in truth. It deserves to be perfect only because existence of its own kind is precluded outside it. The perfect thing is that outside which there is nothing like it in its species — as with the existents in natural things, and all the more so in origination. The body too is a name applying to something perfect in its three dimensions, such that nothing outside it is like it; whatever is like it is from it, and is counted as part of it. The sun is likewise perfect: nothing exists outside it that is like it in its species.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say reflecting on this perfection is a name that applies to the first thing which is the first cause and it is also the first perfect which is the first effect its perfection comes from the relation of its existence to that from which its existence came and its perfection comes from its relation to that upon which its essence rests and this is analogous to origination and the originator in their proper order origination is not something other than the originator it is that by which the originator is itself what then is it it is a single essence considered in relation to that from which its existence came it is origination considered in relation to that upon which its essence rests bearing the mark of temporal occurrence it is originated thus the first intellect is perfection and it is also the perfect in truth it deserves to be perfect only because existence of its own kind is precluded outside it the perfect thing is that outside which there is nothing like it in its species as with the existents in natural things and all the more so in origination the body too is a name applying to something perfect in its three dimensions such that nothing outside it is like it whatever is like it is from it and is counted as part of it the sun is likewise perfect nothing exists outside it that is like it in its species', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 14, NULL, 'In sum, the existence of what lies below the First Intellect, in relation to it, is a deficient existence. Yet that deficiency is not in its essence but in its rank — in relation to what is above it. All things are perfect in their essences, since their existence comes from the perfection that is the First Intellect, and there is no deficiency in them. Were they deficient in their essences, their existence from perfection would be impossible; and it would likewise be impossible for anything to come forth from what is deficient, since the deficient cannot even complete its own essence, let alone bring something else into existence from it. Deficiency attaches to things only when they are considered in relation to what is above them in rank, not in their essences. The essence, insofar as essences belong to a single thing, is like numbers: numbers are perfect in their essences, and their deficiency arises only from their relation to others by which their existence is. Likewise, all the existents of the world are perfect — with no deficiency in them insofar as they are bodies — and deficient only in respect of their ranks among forms, which differ when some forms are nobler than others. The human being is the noblest of all forms: perfect in his essence like all the others, and deficient only in relation to what is above him. And if the matter is thus in bodily things, then what is not a body follows the same order in respect of rank — like for like.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'in sum the existence of what lies below the first intellect in relation to it is a deficient existence yet that deficiency is not in its essence but in its rank in relation to what is above it all things are perfect in their essences since their existence comes from the perfection that is the first intellect and there is no deficiency in them were they deficient in their essences their existence from perfection would be impossible and it would likewise be impossible for anything to come forth from what is deficient since the deficient cannot even complete its own essence let alone bring something else into existence from it deficiency attaches to things only when they are considered in relation to what is above them in rank not in their essences the essence insofar as essences belong to a single thing is like numbers numbers are perfect in their essences and their deficiency arises only from their relation to others by which their existence is likewise all the existents of the world are perfect with no deficiency in them insofar as they are bodies and deficient only in respect of their ranks among forms which differ when some forms are nobler than others the human being is the noblest of all forms perfect in his essence like all the others and deficient only in relation to what is above him and if the matter is thus in bodily things then what is not a body follows the same order in respect of rank like for like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 15, NULL, 'For this reason Allah, exalted, said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'for this reason allah exalted said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 16, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ"We shall show them Our signs in the horizons and within themselves until it becomes clear to them that it is the truth."', '', NULL, 'Fussilat: 53', NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق we shall show them our signs in the horizons and within themselves until it becomes clear to them that it is the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 17, NULL, 'That is: We shall establish for them the Imams and the limits, in the manifest and the hidden, that they may be guided to what the state of the observable bodies is, and of the souls whose actions exist — upon what had been hidden from them of the knowledge of the limits of Allah, which are the truth — so that the truth of the form may become clear to them.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'that is we shall establish for them the imams and the limits in the manifest and the hidden that they may be guided to what the state of the observable bodies is and of the souls whose actions exist upon what had been hidden from them of the knowledge of the limits of allah which are the truth so that the truth of the form may become clear to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 19, NULL, 'The author of al-Islah said: what stands in need of perfection is the act of the soul, not the essence of the soul, because the soul''s act is completed only in time. The emanation of the soul is with time, just as the First Intellect and time are one, for the First Originator, origination, time, and perfection are one existent. The Creator originated all originated things at once. The soul''s need to derive benefit from the First is not a deficiency in its essence — just as the First was not deficient though it stood in need of the command. Completion and deficiency appear in the act of the soul, not in its essence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al islah said what stands in need of perfection is the act of the soul not the essence of the soul because the souls act is completed only in time the emanation of the soul is with time just as the first intellect and time are one for the first originator origination time and perfection are one existent the creator originated all originated things at once the souls need to derive benefit from the first is not a deficiency in its essence just as the first was not deficient though it stood in need of the command completion and deficiency appear in the act of the soul not in its essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 20, NULL, 'The author of al-Nusra said: he did not recognize that the Intellect does not stand in need of anything in the way the soul needs to derive benefit from the Intellect. The state of the Intellect and matter is not like the state of the soul and the Intellect, for matter, from the side of the Intellect, is nothing other than the Intellect itself — their identity is one. It is impossible to say that a thing stands in need of what it itself is; the need of a thing for another thing arises only when they are other than each other. This is what they say.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra said he did not recognize that the intellect does not stand in need of anything in the way the soul needs to derive benefit from the intellect the state of the intellect and matter is not like the state of the soul and the intellect for matter from the side of the intellect is nothing other than the intellect itself their identity is one it is impossible to say that a thing stands in need of what it itself is the need of a thing for another thing arises only when they are other than each other this is what they say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 21, NULL, 'We say: the statement of the author of al-Nusra is a reply to what the author of al-Islah maintained regarding the Intellect''s need for the command only. Since the discourse concerned the principles that come out of the natural world, the statement of the author of al-Nusra on this point is closer to the truth than that of the author of al-Islah. What may properly be said to stand in need of perfection — completed only in time, because it is an emanation from the natural world and not from outside it — is the souls that attain the degree of perfection, that is, the ascent to the degree of the second perfection, only in time, and whose existence is an emanative existence. If the statement of the author of al-Islah is understood in this light, it is correct.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say the statement of the author of al nusra is a reply to what the author of al islah maintained regarding the intellects need for the command only since the discourse concerned the principles that come out of the natural world the statement of the author of al nusra on this point is closer to the truth than that of the author of al islah what may properly be said to stand in need of perfection completed only in time because it is an emanation from the natural world and not from outside it is the souls that attain the degree of perfection that is the ascent to the degree of the second perfection only in time and whose existence is an emanative existence if the statement of the author of al islah is understood in this light it is correct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 23, NULL, 'The statement of the author of al-Islah — that the Intellect and time are one, because the Originator, origination, time, and perfection are one existent — is not correct. Time is the number of the motions of the degrees of the celestial sphere; it is the imagined duration between the motion of the first degree and the motion of the following degree to where the first had been. Origination, which is the Intellect, and perfection — their existence precedes the sphere by whose degrees'' motions the existence of time comes to be. To attach the existence of time to the existence of the First Intellect, and to hold that belief, contradicts what the law of the guiding دَعْوَة rests upon. We have explained the coming-to-be of time, what precedes it in existence, and the indication of this from the ordinances of the prophetic Law in our book known as رَاحَةُ الْعَقْلِ (Peace of Mind), in terms sufficient for those who seek.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the statement of the author of al islah that the intellect and time are one because the originator origination time and perfection are one existent is not correct time is the number of the motions of the degrees of the celestial sphere it is the imagined duration between the motion of the first degree and the motion of the following degree to where the first had been origination which is the intellect and perfection their existence precedes the sphere by whose degrees motions the existence of time comes to be to attach the existence of time to the existence of the first intellect and to hold that belief contradicts what the law of the guiding دعوه rests upon we have explained the coming to be of time what precedes it in existence and the indication of this from the ordinances of the prophetic law in our book known as راحه العقل peace of mind in terms sufficient for those who seek', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 25, NULL, 'The author of al-Nusra said: were it not for the Intellect''s denial of divinity from itself, the Following one would not have been able to carry its knowledge beyond the rank of the Intellect to the Originator. What deficiency could be more evident than this — that it knows the Originator only by way of the First?', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra said were it not for the intellects denial of divinity from itself the following one would not have been able to carry its knowledge beyond the rank of the intellect to the originator what deficiency could be more evident than this that it knows the originator only by way of the first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 26, NULL, 'We say: that may not be believed of the Following one. The power flowing through all the noble existents in the world of unity gives them knowledge that they have an Originator. Were it not for that power, nothing would have existence or subsistence, and all would vanish away. For this reason every thing deserves the name of oneness: though it be multiple in its essence, its share of that power is unseen, while the justice in it is evident. It is impossible to conceive of a single one of the human kind not knowing that it has a Creator, or imagining that it has no Creator — let alone that this should be thought of that great and majestic Limit. We say rather: it apprehends that from which its existence came, knowing it as the True Object of worship, even if there be a god within it. If we then apply to the First Intellect what the author of al-Nusra mentioned, and to the Following one what he said of it, it would be obligatory that the Asas — whose standing is in the world of body — stand in the place of the Following one in the world of Intellect, since without the Speaker one would not know one has a god. But the matter is not so, for each of the two has a portion from Allah, and the Speaker precedes it in rank only by his nearness to the First and his coming after it. For this reason Allah said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say that may not be believed of the following one the power flowing through all the noble existents in the world of unity gives them knowledge that they have an originator were it not for that power nothing would have existence or subsistence and all would vanish away for this reason every thing deserves the name of oneness though it be multiple in its essence its share of that power is unseen while the justice in it is evident it is impossible to conceive of a single one of the human kind not knowing that it has a creator or imagining that it has no creator let alone that this should be thought of that great and majestic limit we say rather it apprehends that from which its existence came knowing it as the true object of worship even if there be a god within it if we then apply to the first intellect what the author of al nusra mentioned and to the following one what he said of it it would be obligatory that the asas whose standing is in the world of body stand in the place of the following one in the world of intellect since without the speaker one would not know one has a god but the matter is not so for each of the two has a portion from allah and the speaker precedes it in rank only by his nearness to the first and his coming after it for this reason allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 27, NULL, 'Sayingلَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ وَلَا اللَّيْلُ سَابِقُ النَّهَارِ وَكُلٌّ فِي فَلَكٍ يَسْبَحُونَ"It is not for the sun to overtake the moon, nor does the night outstrip the day; and each is swimming in an orbit."', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'sayingلا الشمس ينبغي لها ان تدرك القمر ولا الليل سابق النهار وكل في فلك يسبحون it is not for the sun to overtake the moon nor does the night outstrip the day and each is swimming in an orbit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 28, NULL, 'All, from the side of movement, are one; and by ranks they differ.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'all from the side of movement are one and by ranks they differ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 30, NULL, 'The author of al-Nusra said: and enough for you, as proof of deficiency, is that all the ancients placed the soul in the station of the form, and the Intellect in the station of prime matter and material, saying: forms ever yearn and long for materials, and materials have no subsistence without forms.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'the author of al nusra said and enough for you as proof of deficiency is that all the ancients placed the soul in the station of the form and the intellect in the station of prime matter and material saying forms ever yearn and long for materials and materials have no subsistence without forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 31, NULL, 'We say: his statement that the soul is a form is true. But his statement that the Intellect is in the station of prime matter and material — since the discourse was about the First Intellect — was an overreach against the author of al-Islah, addressing him with terms that do not apply to his subject. For "Intellect" is a shared name, and what the author of al-Nusra said does not hold for the separate originative and first emanative intellects; it is correct only concerning the other intellects that exist within the natural world — the intellect in potency and the intellect in act. Since the discourse was about what is separate, to apply to it what is said of natural things and to use that as a basis for contradiction was an overreach.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'we say his statement that the soul is a form is true but his statement that the intellect is in the station of prime matter and material since the discourse was about the first intellect was an overreach against the author of al islah addressing him with terms that do not apply to his subject for intellect is a shared name and what the author of al nusra said does not hold for the separate originative and first emanative intellects it is correct only concerning the other intellects that exist within the natural world the intellect in potency and the intellect in act since the discourse was about what is separate to apply to it what is said of natural things and to use that as a basis for contradiction was an overreach', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 32, NULL, 'His statement that forms ever yearn and long for materials, and that materials have no subsistence without forms, is also incorrect. Forms do not long for materials, for their existence is not for the sake of materials and they are not what acquire materials. It is materials that yearn for forms, since their existence is for the sake of forms and it is they that acquire forms. Matter is considered in relation to the base form and to the nobler form.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'his statement that forms ever yearn and long for materials and that materials have no subsistence without forms is also incorrect forms do not long for materials for their existence is not for the sake of materials and they are not what acquire materials it is materials that yearn for forms since their existence is for the sake of forms and it is they that acquire forms matter is considered in relation to the base form and to the nobler form', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the perfect and perfection', '1. The Perfect and Perfection', 33, NULL, 'This being so — and he has run the soul in the course of the form and the Intellect in the course of matter, and ruled that materials have no subsistence without forms — it is as though he has made it necessary that the existence of the Intellect be by the soul. Yet how could that belief hold for something whose existence was an originative existence? Or how could it be conceived that the Intellect be the cause of the existence of the Intellect and the soul, while the discourse is about what is separate and comes out of the world of nature? Never. For it is known that the existence of the Following one is by the Preceding one, not the Preceding one''s existence by the Following one. That is a plain fallacy, arising only from carrying upon what is natural what is said about the world of origination. As for what is in the world of origination and the first emanation — the existents from the abode of nature, of the Intellect and the soul, which are of the category of the second emanation — the matter is only as he mentioned, and it is correct from that aspect.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 1 the perfect and perfection', 'this being so and he has run the soul in the course of the form and the intellect in the course of matter and ruled that materials have no subsistence without forms it is as though he has made it necessary that the existence of the intellect be by the soul yet how could that belief hold for something whose existence was an originative existence or how could it be conceived that the intellect be the cause of the existence of the intellect and the soul while the discourse is about what is separate and comes out of the world of nature never for it is known that the existence of the following one is by the preceding one not the preceding ones existence by the following one that is a plain fallacy arising only from carrying upon what is natural what is said about the world of origination as for what is in the world of origination and the first emanation the existents from the abode of nature of the intellect and the soul which are of the category of the second emanation the matter is only as he mentioned and it is correct from that aspect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 0, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 1, NULL, 'The Intellect is the first mean and the Soul is the second mean; and the first mean stands nearer to the Cause than the second. Nearness and rank can arise only from perfection and nobility, and remoteness only from deficiency and lack of nobility.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the intellect is the first mean and the soul is the second mean and the first mean stands nearer to the cause than the second nearness and rank can arise only from perfection and nobility and remoteness only from deficiency and lack of nobility', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 2, NULL, 'We say: this statement carries no true meaning when applied to the originative and emanative first Intellects. To be a mean requires two ends, and it is not admissible to call the First Intellect a mean, since that from which its existence comes is not of the same kind as it — there is no end on that side, no shared nature that could anchor a mean — and since the First Intellect stands alone in existence, of a kind that nothing precedes.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say this statement carries no true meaning when applied to the originative and emanative first intellects to be a mean requires two ends and it is not admissible to call the first intellect a mean since that from which its existence comes is not of the same kind as it there is no end on that side no shared nature that could anchor a mean and since the first intellect stands alone in existence of a kind that nothing precedes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 3, NULL, 'How could one even imagine that the First of ones is a mean, when nothing of its own kind of existence precedes it, that it might stand between that and what comes after? The supposition itself is impossible: the First Intellect has a first existence, and what has a first existence cannot be called a mean. A thing deserves the name "mean" only when something of its own kind of existence precedes it — establishing an affinity on one side — and something suited to it in certain respects follows it — establishing an affinity on the other. Those two are its ends, and it is a mean between them. But between the First Intellect and its Originator, exalted be His mention, there is no affinity whatsoever. The First Intellect is not of the kind of His existence, so it cannot be a mean between Him and what lies below it, and there is no occasion for it to be a mean between itself and its Originator. What stands between it and its Originator — the cause by which it exists — is other than it. And what is called the mediator between it and what lies below it is the very essence of origination, the Cause said to be at once originating and originated, as we have shown in The Illuminated Epistle and in our well-known book Peace of Mind.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'how could one even imagine that the first of ones is a mean when nothing of its own kind of existence precedes it that it might stand between that and what comes after the supposition itself is impossible the first intellect has a first existence and what has a first existence cannot be called a mean a thing deserves the name mean only when something of its own kind of existence precedes it establishing an affinity on one side and something suited to it in certain respects follows it establishing an affinity on the other those two are its ends and it is a mean between them but between the first intellect and its originator exalted be his mention there is no affinity whatsoever the first intellect is not of the kind of his existence so it cannot be a mean between him and what lies below it and there is no occasion for it to be a mean between itself and its originator what stands between it and its originator the cause by which it exists is other than it and what is called the mediator between it and what lies below it is the very essence of origination the cause said to be at once originating and originated as we have shown in the illuminated epistle and in our well known book peace of mind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 4, NULL, 'Given all this, the author of al-Nusra''s inference in support of his position carries no force — what has already been said about deficiency and nobility is sufficient. Deficiency attaches to the Following only in relation to the First Intellect, not in its own essence. Its essence is sound, with no deficiency in it; it possesses completeness. It is only in relation to what precedes it that it stands at a lesser rank. Consider the Speaker and the Foundation, the Sun and the Moon: the Foundation and the Moon are each perfect in their own essence, with no deficiency in them; yet set beside their counterparts — the Speaker and the Sun — each is deficient in rank. The author of al-Nusra binds the Following to deficiency by relating it to what precedes it, while the author of al-Islah binds its essence to perfection, since it emanates from the Perfection that is its Cause. Each is right on his own side — except that the author of al-Nusra wrongs the author of al-Islah by taking him in a direction he did not intend and that his purpose does not touch.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'given all this the author of al nusras inference in support of his position carries no force what has already been said about deficiency and nobility is sufficient deficiency attaches to the following only in relation to the first intellect not in its own essence its essence is sound with no deficiency in it it possesses completeness it is only in relation to what precedes it that it stands at a lesser rank consider the speaker and the foundation the sun and the moon the foundation and the moon are each perfect in their own essence with no deficiency in them yet set beside their counterparts the speaker and the sun each is deficient in rank the author of al nusra binds the following to deficiency by relating it to what precedes it while the author of al islah binds its essence to perfection since it emanates from the perfection that is its cause each is right on his own side except that the author of al nusra wrongs the author of al islah by taking him in a direction he did not intend and that his purpose does not touch', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 5, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 6, NULL, 'If he says — meaning the author of al-Islah — "I do not mean that the Intellect is like the Soul in the matter of perfection," we say to him: then it is either better than the Soul or more deficient than it. He will not claim that the Soul is superior to the Intellect, so it remains for him to say that the Soul is deficient.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'if he says meaning the author of al islah i do not mean that the intellect is like the soul in the matter of perfection we say to him then it is either better than the soul or more deficient than it he will not claim that the soul is superior to the intellect so it remains for him to say that the soul is deficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 7, NULL, 'We say: the author of al-Islah may well not say what the author of al-Nusra has undertaken to report on his behalf. Rather, he says that all things are perfect in their own essences, and that none of them merits deficiency except in relation to what stands at a higher degree — so that the higher possesses a rank this thing does not. Once this connection is understood, the nature of the wrong done to him is plain.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say the author of al islah may well not say what the author of al nusra has undertaken to report on his behalf rather he says that all things are perfect in their own essences and that none of them merits deficiency except in relation to what stands at a higher degree so that the higher possesses a rank this thing does not once this connection is understood the nature of the wrong done to him is plain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 8, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 9, NULL, 'Among the clearest proofs of the Soul''s deficiency and the Intellect''s perfection is the saying of God, exalted be He:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'among the clearest proofs of the souls deficiency and the intellects perfection is the saying of god exalted be he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 10, NULL, 'Sayingوَمِنْ آيَاتِهِ اللَّيْلُ، وَالنَّهَارُ، وَالشَّمْسُ، وَالْقَمَرُ"And among His signs are the night, the day, the sun, and the moon."', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'sayingومن اياته الليل والنهار والشمس والقمر and among his signs are the night the day the sun and the moon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 11, NULL, 'The night and the day stand for the two Foundations, and the sun and the moon for the two Roots: the sun for the First, and the moon for the Following. There is no disagreement among the people of knowledge and wisdom that the moon is of less light than the sun, less in light and radiance, that it draws its light from the sun, and that the sun bestows light upon it. This is what he says.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the night and the day stand for the two foundations and the sun and the moon for the two roots the sun for the first and the moon for the following there is no disagreement among the people of knowledge and wisdom that the moon is of less light than the sun less in light and radiance that it draws its light from the sun and that the sun bestows light upon it this is what he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 12, NULL, 'We say: his own saying makes it clear — the moon is of less light than the sun, less in light and radiance, and draws its light from the sun. Its deficiency attaches to it only by relating it to the sun; in its own essence, there is no deficiency in it, for were it deficient in essence it could not have received light from the sun at all. Because its essence is perfect, it stood ready to receive from the sun what it is able to receive. The author of al-Islah speaks of the perfection of the essence; the author of al-Nusra speaks of its deficiency in its states and accidents, through which its completeness comes. These are two different statements about two different things. The author of al-Islah is wronged — taken in a direction that is not his purpose and not his intent.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say his own saying makes it clear the moon is of less light than the sun less in light and radiance and draws its light from the sun its deficiency attaches to it only by relating it to the sun in its own essence there is no deficiency in it for were it deficient in essence it could not have received light from the sun at all because its essence is perfect it stood ready to receive from the sun what it is able to receive the author of al islah speaks of the perfection of the essence the author of al nusra speaks of its deficiency in its states and accidents through which its completeness comes these are two different statements about two different things the author of al islah is wronged taken in a direction that is not his purpose and not his intent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 13, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 14, NULL, 'Another indication of the Soul''s deficiency is that the wise set the Intellect in the station of the spirit to the Soul, and set the Soul in the station of the body to the Intellect. They did this only because they recognized the Soul''s deficiency and the Intellect''s completeness, and so likened the Soul to the deficient thing and the Intellect to the complete thing.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'another indication of the souls deficiency is that the wise set the intellect in the station of the spirit to the soul and set the soul in the station of the body to the intellect they did this only because they recognized the souls deficiency and the intellects completeness and so likened the soul to the deficient thing and the intellect to the complete thing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 15, NULL, 'We say: with this he has only added a further clarification of what we have already said — that the deficiency is not in the Soul''s essence but in other things, its states. Even so, the meaning of his words holds true only for the beings of the world and the second emanation. The drawing of benefit belongs only to the souls in the world of nature, that they may reach their second completeness; in their own essence they are complete and perfect, though deficient in the intelligibles they do not yet possess — intelligibles that run to them as the spirit runs to the body. The second, which is the first emanation, follows a different way: its completeness and perfection were given at the beginning of its existence, not through time and the drawing of benefit, but only through a deficiency of rank below what precedes it, through precedence and posteriority.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say with this he has only added a further clarification of what we have already said that the deficiency is not in the souls essence but in other things its states even so the meaning of his words holds true only for the beings of the world and the second emanation the drawing of benefit belongs only to the souls in the world of nature that they may reach their second completeness in their own essence they are complete and perfect though deficient in the intelligibles they do not yet possess intelligibles that run to them as the spirit runs to the body the second which is the first emanation follows a different way its completeness and perfection were given at the beginning of its existence not through time and the drawing of benefit but only through a deficiency of rank below what precedes it through precedence and posteriority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 16, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 17, NULL, 'Even if the Soul had no deficiency other than that nature lies upon its horizon, this alone would suffice. The Soul has two ends: one toward the Intellect and one toward nature. The Intellect is not so — its two ends are one toward the Word and the other toward the Soul, and nothing of it clings to dark nature, because of its perfection and completeness. That an end of the Soul clings to nature, because nature lies upon its horizon — this alone, for whoever contemplates it, is enough to establish the truth of the Soul''s deficiency and the Intellect''s perfection. This is what he says.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'even if the soul had no deficiency other than that nature lies upon its horizon this alone would suffice the soul has two ends one toward the intellect and one toward nature the intellect is not so its two ends are one toward the word and the other toward the soul and nothing of it clings to dark nature because of its perfection and completeness that an end of the soul clings to nature because nature lies upon its horizon this alone for whoever contemplates it is enough to establish the truth of the souls deficiency and the intellects perfection this is what he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 18, NULL, 'We say: this statement proceeds without order. That nature lies upon the horizon of the Following — which he calls the Soul — does not earn it any deficiency. On the contrary, it indicates a perfection belonging to it: nature moves toward the Following because nature is deficient in relation to it, while the Following, in relation to nature, is noble and perfect, distinguished by what nature is not distinguished by. And yet the essential reality of both — I mean the essence of the Following and the essence of nature — is perfect, since both emanate from Perfection.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say this statement proceeds without order that nature lies upon the horizon of the following which he calls the soul does not earn it any deficiency on the contrary it indicates a perfection belonging to it nature moves toward the following because nature is deficient in relation to it while the following in relation to nature is noble and perfect distinguished by what nature is not distinguished by and yet the essential reality of both i mean the essence of the following and the essence of nature is perfect since both emanate from perfection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 19, NULL, 'As for his saying that the Intellect has two ends, one toward the Word and the other toward the Soul: the Intellect is not a thing other than the Word, nor is the Word a thing other than the Intellect. The essence is one and the entity is one; it is only by relation that it merits the various names assigned to it. What has already been said on this point, when the name "mean" was discussed, makes this plain.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'as for his saying that the intellect has two ends one toward the word and the other toward the soul the intellect is not a thing other than the word nor is the word a thing other than the intellect the essence is one and the entity is one it is only by relation that it merits the various names assigned to it what has already been said on this point when the name mean was discussed makes this plain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 20, NULL, 'As for his saying that nothing of the Intellect clings to dark nature because of its perfection and completeness, while an end of the Soul has clung to nature because nature lies upon its horizon: it is not the Following that has clung to nature and loved it and desired it. It is nature that has loved the Following; it is nature that moves toward it and seeks union with it. To hold otherwise — to picture an end of the Following as clinging to nature — is an error. The most charitable reading of his words is that he meant the Following pours forth upon nature, and has called that outpouring a clinging.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'as for his saying that nothing of the intellect clings to dark nature because of its perfection and completeness while an end of the soul has clung to nature because nature lies upon its horizon it is not the following that has clung to nature and loved it and desired it it is nature that has loved the following it is nature that moves toward it and seeks union with it to hold otherwise to picture an end of the following as clinging to nature is an error the most charitable reading of his words is that he meant the following pours forth upon nature and has called that outpouring a clinging', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 21, NULL, 'The author of al-Islah said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al islah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 22, NULL, 'The deficient is the act of the Soul, not the essence of the Soul; and it is its act that is perfected, not its essence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the deficient is the act of the soul not the essence of the soul and it is its act that is perfected not its essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 23, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 24, NULL, 'This statement is self-contradictory. If the act is deficient, the deficiency must come from one of three places: a deficiency in the essence of the agent, a deficiency in the substance from which the agent acts, or a deficiency in both. If it comes from a deficiency in the essence of the agent, then he has affirmed the deficiency of the Soul, since the Soul is the agent. If it comes from a deficiency in the substance, then he has affirmed an eternal substance — which is a departure from the doctrine of religion and an inclination toward the doctrine of Abu Zakariyya al-Razi (أَبُو زَكَرِيَّا الرَّازِي) and those who hold the pre-eternity of matter. It has already been suspected of this book''s author that he leaned in that direction, since he made time pre-eternal alongside the Intellect, which is the core of his doctrine. And if the deficiency of the act comes from both, he has embraced both positions at once: affirming the deficiency of the Soul as agent, and affirming the pre-eternity of matter. Whatever he says, he ends up affirming the deficiency of the Soul. This is what he says.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'this statement is self contradictory if the act is deficient the deficiency must come from one of three places a deficiency in the essence of the agent a deficiency in the substance from which the agent acts or a deficiency in both if it comes from a deficiency in the essence of the agent then he has affirmed the deficiency of the soul since the soul is the agent if it comes from a deficiency in the substance then he has affirmed an eternal substance which is a departure from the doctrine of religion and an inclination toward the doctrine of abu zakariyya al razi ابو زكريا الرازي and those who hold the pre eternity of matter it has already been suspected of this books author that he leaned in that direction since he made time pre eternal alongside the intellect which is the core of his doctrine and if the deficiency of the act comes from both he has embraced both positions at once affirming the deficiency of the soul as agent and affirming the pre eternity of matter whatever he says he ends up affirming the deficiency of the soul this is what he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 25, NULL, 'We say: the author of al-Islah''s position and his purpose in what he said about deficiency and perfection have already been set out. As for the author of al-Nusra''s argument here, it is sophistry, injustice, and a departure from the bounds of knowledge.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say the author of al islahs position and his purpose in what he said about deficiency and perfection have already been set out as for the author of al nusras argument here it is sophistry injustice and a departure from the bounds of knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 26, NULL, 'He argued first that if the deficiency of the act comes from the essence of the agent — and the agent is the Soul — then the Soul is deficient. Yet the author of al-Islah has made plain that deficiency does not attach to the essence of the Soul, which is the Following, but to its act in the sense of the thing acted upon. This frees him from this division entirely.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'he argued first that if the deficiency of the act comes from the essence of the agent and the agent is the soul then the soul is deficient yet the author of al islah has made plain that deficiency does not attach to the essence of the soul which is the following but to its act in the sense of the thing acted upon this frees him from this division entirely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 27, NULL, 'He argued secondly that if the deficiency comes from the substance, then he has affirmed an eternal substance. But Perfection and the Perfect — the First and the Second — have an eternity that is not a first eternity affirmed of them; how much more, then, the deficient? If that is so, deficiency belongs only to the substances that receive their perfection, not to that from which perfection is received. This is well known in natural science: deficiency arises from the side of the recipients, not from the side of that from which it is received. Consider the heat of the sun: bodies quick to be affected receive it — wax, for example, which softens under it — while other bodies refuse it, like stone and iron, which are not quickly affected. The source of the heat is one; the deficiency lies in the others.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'he argued secondly that if the deficiency comes from the substance then he has affirmed an eternal substance but perfection and the perfect the first and the second have an eternity that is not a first eternity affirmed of them how much more then the deficient if that is so deficiency belongs only to the substances that receive their perfection not to that from which perfection is received this is well known in natural science deficiency arises from the side of the recipients not from the side of that from which it is received consider the heat of the sun bodies quick to be affected receive it wax for example which softens under it while other bodies refuse it like stone and iron which are not quickly affected the source of the heat is one the deficiency lies in the others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 28, NULL, 'He argued thirdly that the author of al-Islah inclined toward the doctrine of Abu Zakariyya in the way he described — and this too is a departure from the bounds of knowledge and a transgression. He did him no justice: neither in how he framed the division, nor in what followed it, when he charged him with holding both positions at once — deficiency and the pre-eternity of matter.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'he argued thirdly that the author of al islah inclined toward the doctrine of abu zakariyya in the way he described and this too is a departure from the bounds of knowledge and a transgression he did him no justice neither in how he framed the division nor in what followed it when he charged him with holding both positions at once deficiency and the pre eternity of matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 29, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 30, NULL, 'As for his claim that the Soul became perfect only because it emanated from the First Intellect, which is Perfection, and that what emanates from Perfection cannot but be perfect — this is not right. It does not follow that the Soul must be perfect simply because it emanates from the perfect Intellect. Were that necessary, then what emanates from the Soul — namely matter and form — would also be perfect, and what emanates from matter and form would likewise be perfect, and so on down to the single, indivisible individuals, so that all would be perfect. This saying entails that the whole world is perfect, with no deficiency anywhere in it.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'as for his claim that the soul became perfect only because it emanated from the first intellect which is perfection and that what emanates from perfection cannot but be perfect this is not right it does not follow that the soul must be perfect simply because it emanates from the perfect intellect were that necessary then what emanates from the soul namely matter and form would also be perfect and what emanates from matter and form would likewise be perfect and so on down to the single indivisible individuals so that all would be perfect this saying entails that the whole world is perfect with no deficiency anywhere in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 31, NULL, 'We say: the gist of his saying is this — if the Soul were perfect by virtue of emanating from the First Intellect, which is Perfection, then matter and form, by their emanating from the Soul, would likewise be perfect, and so would everything emanating from matter and form, down to the individuals as he supposes, so that the whole world would be perfect with no deficiency in it. We have already shown what the author of al-Islah meant in saying that the Soul is perfect. The author of al-Nusra''s argument in this chapter is not thoroughly examined.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say the gist of his saying is this if the soul were perfect by virtue of emanating from the first intellect which is perfection then matter and form by their emanating from the soul would likewise be perfect and so would everything emanating from matter and form down to the individuals as he supposes so that the whole world would be perfect with no deficiency in it we have already shown what the author of al islah meant in saying that the soul is perfect the author of al nusras argument in this chapter is not thoroughly examined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 32, NULL, 'Matter is not emanated from the Soul, and the individuals are not, as he supposed, indivisible — all individuals are divided into their parts. Matter is emanated together with the Soul from that which precedes it in existence, not from the Soul itself. The proof is this: the Soul, which is the Following, does not have a first existence. There is therefore no existence of its own kind found alongside it, nor does anything rise above it in rank as with the First, which is the First Intellect. Its existence is a second existence. And whatever has a second existence does not exist in isolation — with it there must be an existence of its own kind, such that the two share the same kind.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'matter is not emanated from the soul and the individuals are not as he supposed indivisible all individuals are divided into their parts matter is emanated together with the soul from that which precedes it in existence not from the soul itself the proof is this the soul which is the following does not have a first existence there is therefore no existence of its own kind found alongside it nor does anything rise above it in rank as with the first which is the first intellect its existence is a second existence and whatever has a second existence does not exist in isolation with it there must be an existence of its own kind such that the two share the same kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 33, NULL, 'For the First Thing — from which this Soul, the Following, came to be — is that which nothing of its own kind of existence precedes, which is one in its existence. This was solely for the sake of the transcendence of God, exalted be He, who brought it into existence free of relations, additions, multiplicity, and all that by which a thing is described in its kinds. They have found — I mean the relations and the additions — that in the active causes these are a cause for what comes to be from them being more than one, since the existence of multiplicity in caused things corresponds to what their causes and grounds possess of relations.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'for the first thing from which this soul the following came to be is that which nothing of its own kind of existence precedes which is one in its existence this was solely for the sake of the transcendence of god exalted be he who brought it into existence free of relations additions multiplicity and all that by which a thing is described in its kinds they have found i mean the relations and the additions that in the active causes these are a cause for what comes to be from them being more than one since the existence of multiplicity in caused things corresponds to what their causes and grounds possess of relations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 34, NULL, 'And so, since God, exalted be He, is too prior for another to precede Him or to exist with Him, and too exalted to be diversified by attributes and relations — since He, exalted be He, is the Existentiator, the Originator, the Cause that has no cause — it was impossible, given His purity, His holiness, and His exaltation above multiplicity, that there should come from Him anything other than one. And this one, which is the First Intellect, stood in two relations: one its being a cause for the existence of what lies below it, and the other its being an effect, since it is originated and brought into being. It was therefore necessary that what comes from it should be two, corresponding to the two relations in which its essence stands. What came from the first relation is the second Intellect, and from the other relation came the matter of which the spheres are made, and the rest of the existents of the world of body. Then, when the existent passes beyond the one into coming-to-be, it is only two, since there is not', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'and so since god exalted be he is too prior for another to precede him or to exist with him and too exalted to be diversified by attributes and relations since he exalted be he is the existentiator the originator the cause that has no cause it was impossible given his purity his holiness and his exaltation above multiplicity that there should come from him anything other than one and this one which is the first intellect stood in two relations one its being a cause for the existence of what lies below it and the other its being an effect since it is originated and brought into being it was therefore necessary that what comes from it should be two corresponding to the two relations in which its essence stands what came from the first relation is the second intellect and from the other relation came the matter of which the spheres are made and the rest of the existents of the world of body then when the existent passes beyond the one into coming to be it is only two since there is not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 35, NULL, 'For beyond the rank of the one in existence there is nothing but two; and beyond the individual there is nothing but the pair, which is plurality. If the first thing in the order of existents is one, then what follows it — as the intellect conceives — is two: the pair, which is the multitude. And if what follows is two, then one of those two is what we call the Soul, and the other is what we call اَلْهَيُولَى, the matter from which the spheres, the stars, and all that lies beneath them come forth.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'for beyond the rank of the one in existence there is nothing but two and beyond the individual there is nothing but the pair which is plurality if the first thing in the order of existents is one then what follows it as the intellect conceives is two the pair which is the multitude and if what follows is two then one of those two is what we call the soul and the other is what we call الهيولي the matter from which the spheres the stars and all that lies beneath them come forth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 37, NULL, 'The foundation of religion and its ordinances rests upon a balancing of existents against their correspondences, so that their arrangement may point toward those existents among the higher limits that lie hidden from sight. The Book and the Sharia proceed from the side of the Speaker, and the establishment of the Foundation stands as their interpreter, likewise proceeding from the side of the Speaker. This is the clearest sign that what proceeds from the First Intellect — which stands in its own world as the Speaker stands in the world of body — is the Follower; and that Follower is the Soul and اَلْهَيُولَى together, just as the Book and the Foundation are the two that proceed from the side of the Speaker.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the foundation of religion and its ordinances rests upon a balancing of existents against their correspondences so that their arrangement may point toward those existents among the higher limits that lie hidden from sight the book and the sharia proceed from the side of the speaker and the establishment of the foundation stands as their interpreter likewise proceeding from the side of the speaker this is the clearest sign that what proceeds from the first intellect which stands in its own world as the speaker stands in the world of body is the follower and that follower is the soul and الهيولي together just as the book and the foundation are the two that proceed from the side of the speaker', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 38, NULL, 'Witness to this is what the Prophet did when he joined the Book and the Itra — whose existence is from him — when he said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'witness to this is what the prophet did when he joined the book and the itra whose existence is from him when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 39, NULL, 'Sayingإِلَّا أَنِّي تَارِكٌ فِيكُمُ الثَّقَلَيْنِ كِتَابَ اللَّهِ وَعِتْرَتِي ، حبل ممدود من السماء الى الأرض ، طرف منه بيد الله وطرف منه بايديكم، فتمسكوا بها لن تضلوا ما ان تمسكتم بهما، وقد سألت ربي ان يردا عليّ الحوض كهاتين"Indeed, I leave among you the two weighty things: the Book of God and my Itra, a rope stretched from heaven to earth, one end of it in the hand of God and one end of it in your hands. Hold fast to them, and you will never go astray so long as you hold to them. I have asked my Lord that the two return to me at the basin like these two."', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'sayingالا اني تارك فيكم الثقلين كتاب الله وعترتي حبل ممدود من السماء الي الارض طرف منه بيد الله وطرف منه بايديكم فتمسكوا بها لن تضلوا ما ان تمسكتم بهما وقد سالت ربي ان يردا علي الحوض كهاتين indeed i leave among you the two weighty things the book of god and my itra a rope stretched from heaven to earth one end of it in the hand of god and one end of it in your hands hold fast to them and you will never go astray so long as you hold to them i have asked my lord that the two return to me at the basin like these two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 40, NULL, 'And he joined the two forefingers of both his hands together and said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'and he joined the two forefingers of both his hands together and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 41, NULL, 'Sayingولا اقول كهاتين"And I do not say like these two"', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'sayingولا اقول كهاتين and i do not say like these two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 42, NULL, '— pointing with the forefinger and the middle finger of a single hand, one of them going before the other — and saying: whoever helps them helps me, and whoever forsakes them forsakes me.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'pointing with the forefinger and the middle finger of a single hand one of them going before the other and saying whoever helps them helps me and whoever forsakes them forsakes me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 43, NULL, 'In likening them, in their existence, to his two forefingers, he showed that neither precedes the other. He thus placed himself — in the abode of body — in the rank of the First Intellect in the abode of origination. And he placed what he brought of the Book, and the one he coupled with it from his Itra — who is the Foundation, together with the rest of the Imams (عَلَيْهِمُ السَّلَامُ) — in the rank of what proceeds from the First Intellect as the Second Intellect and as اَلْهَيُولَى, according to what we mentioned in the book Rahat al-Aql. Thus اَلْهَيُولَى does not manifest its nobility — nor the beautiful form that lies within its potency — except through the power of the Soul, which is the Follower, and through the shining of light within both of them. Just as the Book and the Sharia do not announce themselves, nor disclose the wonders of wisdom that lie within and beneath them, except through the interpretation of the Foundation and whoever stands in his place. Thus اَلْهَيُولَى, in its existence, proceeds from the First Intellect together with the Second.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'in likening them in their existence to his two forefingers he showed that neither precedes the other he thus placed himself in the abode of body in the rank of the first intellect in the abode of origination and he placed what he brought of the book and the one he coupled with it from his itra who is the foundation together with the rest of the imams عليهم السلام in the rank of what proceeds from the first intellect as the second intellect and as الهيولي according to what we mentioned in the book rahat al aql thus الهيولي does not manifest its nobility nor the beautiful form that lies within its potency except through the power of the soul which is the follower and through the shining of light within both of them just as the book and the sharia do not announce themselves nor disclose the wonders of wisdom that lie within and beneath them except through the interpretation of the foundation and whoever stands in his place thus الهيولي in its existence proceeds from the first intellect together with the second', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 45, NULL, 'We say: We have stated that nothing of the kind of the First Intellect''s own existence stands alongside it, because its existence — the existence by which it exists — is only a first existence, and the first cannot be more than one. Were it otherwise, the ways of professing divine unity would break down. For if the First Intellect had a counterpart in existence, then the existence of the two together would be caused — since their existence would not proceed from itself — and this would require something prior to both from which their existence comes; and that is forbidden and absurd.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say we have stated that nothing of the kind of the first intellects own existence stands alongside it because its existence the existence by which it exists is only a first existence and the first cannot be more than one were it otherwise the ways of professing divine unity would break down for if the first intellect had a counterpart in existence then the existence of the two together would be caused since their existence would not proceed from itself and this would require something prior to both from which their existence comes and that is forbidden and absurd', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 46, NULL, 'For twoness, as an existent, is a being multiplied in essences; and multiplicity in essences does not derive its existence from another multiplicity in essences. Rather, its existence comes from what precedes it — from what is one in essence in one respect and multiple in meanings in another. And what is one in essence yet multiple in meanings does not have its existence through itself, but through another that is not multiplied, neither in meanings nor in essence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'for twoness as an existent is a being multiplied in essences and multiplicity in essences does not derive its existence from another multiplicity in essences rather its existence comes from what precedes it from what is one in essence in one respect and multiple in meanings in another and what is one in essence yet multiple in meanings does not have its existence through itself but through another that is not multiplied neither in meanings nor in essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 47, NULL, 'It has become clear, then, that if the First Intellect had alongside it a counterpart of the kind of its own existence, the two together would be originated from a one that precedes them. The existence of that one would then depend on its being multiple in meanings — not through itself, but through what precedes it and makes it one. And since nothing stands above the Intellect, it is impossible for the Intellect to have a counterpart of the kind of its own existence. It is therefore established that it is one. And in establishing that the Intellect is one, we establish as well that what proceeds from it is two: the Soul and what is called اَلْهَيُولَى. And since the existence of the Soul and اَلْهَيُولَى is simultaneous, as we have shown, it becomes plain that the claim that اَلْهَيُولَى appears from the Soul is an error.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'it has become clear then that if the first intellect had alongside it a counterpart of the kind of its own existence the two together would be originated from a one that precedes them the existence of that one would then depend on its being multiple in meanings not through itself but through what precedes it and makes it one and since nothing stands above the intellect it is impossible for the intellect to have a counterpart of the kind of its own existence it is therefore established that it is one and in establishing that the intellect is one we establish as well that what proceeds from it is two the soul and what is called الهيولي and since the existence of the soul and الهيولي is simultaneous as we have shown it becomes plain that the claim that الهيولي appears from the soul is an error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 49, NULL, 'As for what the author of al-Nusra committed himself to when he spoke of the deficiency of اَلْهَيُولَى and the Image, and of the deficiency of the world and all it contains, we say:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'as for what the author of al nusra committed himself to when he spoke of the deficiency of الهيولي and the image and of the deficiency of the world and all it contains we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 50, NULL, 'اَلْهَيُولَى and the Image are both complete, and the world with all it contains is perfect and complete, and its parts in themselves are complete and perfect. The proof is this: the complete is that outside of which nothing of the kind of its own existence exists. The world is the sum of اَلْهَيُولَى and the Image together with all the parts of body. Body, in itself, is complete in its three dimensions — nothing that its definition entails is found outside it, but within it. It is therefore complete. And if it is complete, then the author of al-Nusra''s denial of the world''s completeness and perfection is impossible; and since it is impossible, his argument is mere overreach.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'الهيولي and the image are both complete and the world with all it contains is perfect and complete and its parts in themselves are complete and perfect the proof is this the complete is that outside of which nothing of the kind of its own existence exists the world is the sum of الهيولي and the image together with all the parts of body body in itself is complete in its three dimensions nothing that its definition entails is found outside it but within it it is therefore complete and if it is complete then the author of al nusras denial of the worlds completeness and perfection is impossible and since it is impossible his argument is mere overreach', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 51, NULL, 'What suffices as an indication of the world''s perfection is what the author of al-Nusra himself said in his book known as al-Iftikhar, in the chapter of the Command, where he said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'what suffices as an indication of the worlds perfection is what the author of al nusra himself said in his book known as al iftikhar in the chapter of the command where he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 52, NULL, 'Sayingوَصُورَةُ اسْتِغْنَاءِ الْعَالَمِ بِكُلِّيَّتِهِ عَنْ غَيْرِ سِوَاهُ عَدَمُ الْغَيْرِ ، وَاكْتِفَاءُ الْحِكْمَةِ بِمَا فِي كُلِّيَّةِ الْعَالَمِ مِنَ الْغِنْيَةِ وَالْكَمَالِ"The form of the world''s self-sufficiency in its totality, needing nothing other than itself, is the nonexistence of any other, and wisdom''s contentment with the richness and perfection that lie in the totality of the world."', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'sayingوصوره استغناء العالم بكليته عن غير سواه عدم الغير واكتفاء الحكمه بما في كليه العالم من الغنيه والكمال the form of the worlds self sufficiency in its totality needing nothing other than itself is the nonexistence of any other and wisdoms contentment with the richness and perfection that lie in the totality of the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 53, NULL, 'I do not know how this escaped him; perhaps he composed the book al-Iftikhar after the book al-Nusra. As for the disparity found among the parts of the world — on account of which the author of al-Nusra charges it with deficiency — that disparity arises only from the addition of some parts to others in respect of their forms and states, and this is the first perfection that exists. For some parts of the world are given both their first and second perfection from the outset; others receive their second perfection only in the end, by acquisition. The discussion has therefore made plain that the deficiency the author of al-Nusra speaks of lies only in the states that supervene upon the natural essences — states that appear when some essences are added to others. The completeness of which the author of al-Islah speaks, meanwhile, belongs only to the essences whose existence is a first existence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'i do not know how this escaped him perhaps he composed the book al iftikhar after the book al nusra as for the disparity found among the parts of the world on account of which the author of al nusra charges it with deficiency that disparity arises only from the addition of some parts to others in respect of their forms and states and this is the first perfection that exists for some parts of the world are given both their first and second perfection from the outset others receive their second perfection only in the end by acquisition the discussion has therefore made plain that the deficiency the author of al nusra speaks of lies only in the states that supervene upon the natural essences states that appear when some essences are added to others the completeness of which the author of al islah speaks meanwhile belongs only to the essences whose existence is a first existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 55, NULL, 'The author of al-Nusra said: If, because the Soul emanates from the Intellect — which is the Complete — the Soul must have stature, then likewise, because the Soul emanates from the Intellect — which is the first intermediary and the first originator — the Soul must be an intermediary like the First, and an originator, such that the Soul attains of the virtues what the Intellect attains, and likewise the whole world and its individuals. That is his statement.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said if because the soul emanates from the intellect which is the complete the soul must have stature then likewise because the soul emanates from the intellect which is the first intermediary and the first originator the soul must be an intermediary like the first and an originator such that the soul attains of the virtues what the intellect attains and likewise the whole world and its individuals that is his statement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 56, NULL, 'We say: The demonstration that the Intellect cannot rightly be called the first intermediary has already been set forth; and in sum, what he has advanced here is a corrupt proposition. For when a thing''s existence proceeds from the requirement of another thing — one being cause, the other effect — it does not follow that the effect shares the cause in all its states. If it did, the effect''s very identity would be the cause''s identity and its reality the cause''s reality; nothing could then be said of it except what is said of that identity; it would no longer be a distinct existence, and it could not be said to proceed from the cause by being that very cause. Yet though the effect need not share the cause in all its states, it must share it in some; for if it shared it in none, it would not be an effect of it at all, and the cause would not have brought it into existence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say the demonstration that the intellect cannot rightly be called the first intermediary has already been set forth and in sum what he has advanced here is a corrupt proposition for when a things existence proceeds from the requirement of another thing one being cause the other effect it does not follow that the effect shares the cause in all its states if it did the effects very identity would be the causes identity and its reality the causes reality nothing could then be said of it except what is said of that identity it would no longer be a distinct existence and it could not be said to proceed from the cause by being that very cause yet though the effect need not share the cause in all its states it must share it in some for if it shared it in none it would not be an effect of it at all and the cause would not have brought it into existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 57, NULL, 'Since this is the way things exist in multiplicity, each must share with its cause in one respect and differ from it in another. It follows, then, that the Follower called Soul — which emanates from the First Intellect, the cause of its existence — must resemble it in one respect and differ from it in another. Since this is so, it is plain that when the Follower called Soul has its existence from the Intellect, its being need not resemble the Intellect in all its states; nor does it follow that what is said of the Intellect as cause must also be said of the Follower called Soul. This refutes what the author of al-Nusra said: that if it were necessary, it would be necessary.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'since this is the way things exist in multiplicity each must share with its cause in one respect and differ from it in another it follows then that the follower called soul which emanates from the first intellect the cause of its existence must resemble it in one respect and differ from it in another since this is so it is plain that when the follower called soul has its existence from the intellect its being need not resemble the intellect in all its states nor does it follow that what is said of the intellect as cause must also be said of the follower called soul this refutes what the author of al nusra said that if it were necessary it would be necessary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 59, NULL, 'The author of al-Nusra said: This has many parallels in the sensible world, such as thought and the partial soul. For the partial soul that is in us is in the position of the Intellect, and thought is in the position of the Soul. Yet thought, even though it emanates from the soul, may not be said to be like the soul, because thought perceives what it perceives part by part, and time after time, whereas the soul perceives the whole of what it perceives without time. That is his statement.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'the author of al nusra said this has many parallels in the sensible world such as thought and the partial soul for the partial soul that is in us is in the position of the intellect and thought is in the position of the soul yet thought even though it emanates from the soul may not be said to be like the soul because thought perceives what it perceives part by part and time after time whereas the soul perceives the whole of what it perceives without time that is his statement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 60, NULL, 'We say: The soul — I mean the soul of the human being — has acts, and each of its acts has a name proper to it. When it seeks to grasp some thing, that seeking is called thought (al-fikr). When it regards the forms of the known things that have come to be within its essence, that regarding is called retention (al-hifz). When it imprints its essence with the marks it captures by way of inference or by way of the senses, that imprint is called conception (al-tasawwur). And when it knows that outside itself there are things it wishes to conceive, that will is called striving (al-nuzu) toward them.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'we say the soul i mean the soul of the human being has acts and each of its acts has a name proper to it when it seeks to grasp some thing that seeking is called thought al fikr when it regards the forms of the known things that have come to be within its essence that regarding is called retention al hifz when it imprints its essence with the marks it captures by way of inference or by way of the senses that imprint is called conception al tasawwur and when it knows that outside itself there are things it wishes to conceive that will is called striving al nuzu toward them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 61, NULL, 'Since the soul has acts, and thought is an act of it that does not pass beyond its own essence so as to have an existence apart from its existence, how can it be sound to liken thought to the Follower called Soul — which has an existence other than the existence of the Intellect? And how can it be said that thought perceives part by part, when perception belongs only to the essence of the soul, through its act called thought within itself? And how can it be sound that the soul — the soul of the human being — should perceive the whole without time, when its only path to knowledge is through the senses and inference, passing from particulars to universals in time?', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'since the soul has acts and thought is an act of it that does not pass beyond its own essence so as to have an existence apart from its existence how can it be sound to liken thought to the follower called soul which has an existence other than the existence of the intellect and how can it be said that thought perceives part by part when perception belongs only to the essence of the soul through its act called thought within itself and how can it be sound that the soul the soul of the human being should perceive the whole without time when its only path to knowledge is through the senses and inference passing from particulars to universals in time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 62, NULL, 'Nor does it follow, because thought may not be said to resemble the soul, that the Second Intellect — called the Universal Soul — does not resemble the First Intellect. For thought as it proceeds from human souls does not run in the same course as the Second Intellect from the First Intellect. The Second Intellect is a second existence from origination, subsisting through itself, even though in existence it is one rank below the First. But thought has no existence separate from the soul; rather it is the very identity of the soul, and has no subsistence through itself. Every act of the soul has a cause that makes it necessary: the soul''s being in the world of nature. When the soul departs from that world, these acts are annulled with their cause, and nothing remains subsisting except the essence conceived as pure Intellect.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'nor does it follow because thought may not be said to resemble the soul that the second intellect called the universal soul does not resemble the first intellect for thought as it proceeds from human souls does not run in the same course as the second intellect from the first intellect the second intellect is a second existence from origination subsisting through itself even though in existence it is one rank below the first but thought has no existence separate from the soul rather it is the very identity of the soul and has no subsistence through itself every act of the soul has a cause that makes it necessary the souls being in the world of nature when the soul departs from that world these acts are annulled with their cause and nothing remains subsisting except the essence conceived as pure intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 63, NULL, 'He made the Second Intellect — called the Soul — proceed from the First Intellect in the manner that thought proceeds from the soul. But since the existence of thought is no existence other than the existence of the soul — which he likened to the Intellect — and since thought has no perception of the soul through its own essence, his argument amounts to a denial that the Second Intellect called the Soul has any existence other than the existence of the First Intellect, or any perception like the perception of the First. And that is impossible; for the Follower has an existence other than the existence of the First, and a perception like the perception of the First. It does not deserve to be called an originator, just as the First Existent does not deserve to be called emanated. Both are pure intellects; each has encompassed its own essence and preserved it by its own essence. They are alike in one respect and unlike in another, as the foregoing discussion has established.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'he made the second intellect called the soul proceed from the first intellect in the manner that thought proceeds from the soul but since the existence of thought is no existence other than the existence of the soul which he likened to the intellect and since thought has no perception of the soul through its own essence his argument amounts to a denial that the second intellect called the soul has any existence other than the existence of the first intellect or any perception like the perception of the first and that is impossible for the follower has an existence other than the existence of the first and a perception like the perception of the first it does not deserve to be called an originator just as the first existent does not deserve to be called emanated both are pure intellects each has encompassed its own essence and preserved it by its own essence they are alike in one respect and unlike in another as the foregoing discussion has established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'nothing stands beside the first', '2. Nothing Stands Beside the First', 64, NULL, 'Since this is so, there is no sense in the likenings he drew: no sense in making thought stand as what he likened it to, no sense in placing the human soul in the position of the First Intellect, and no sense in placing thought within it in the position of the Universal Soul. For the nobility of the human soul, and its passage from potency to act, lie entirely in acquisition; and acquisition comes only from the senses as deed and from conception as knowledge. Since the nobility of souls lies in acquisition — part of which is thought and inference as conception — and since thought belongs to souls only so that they may be ennobled by it, his argument is as though he had made the cause of the First Intellect''s nobility to be the Second Intellect called the Soul. And that is an inverted proposition. For the nobility of the Follower and its rank come from what precedes it in existence — the Antecedent — while the nobility of the Antecedent and its rank come from what comes after it. The rule governing what has a second existence — in respect of perfection and completeness — is that it be the reverse of what has a first existence. Neither, therefore, runs in the course of the other in this respect, though they share from another aspect. Yet the author of al-Nusra has judged what has a first existence by what belongs to what has a second existence. And that is impossible.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 2 nothing stands beside the first', 'since this is so there is no sense in the likenings he drew no sense in making thought stand as what he likened it to no sense in placing the human soul in the position of the first intellect and no sense in placing thought within it in the position of the universal soul for the nobility of the human soul and its passage from potency to act lie entirely in acquisition and acquisition comes only from the senses as deed and from conception as knowledge since the nobility of souls lies in acquisition part of which is thought and inference as conception and since thought belongs to souls only so that they may be ennobled by it his argument is as though he had made the cause of the first intellects nobility to be the second intellect called the soul and that is an inverted proposition for the nobility of the follower and its rank come from what precedes it in existence the antecedent while the nobility of the antecedent and its rank come from what comes after it the rule governing what has a second existence in respect of perfection and completeness is that it be the reverse of what has a first existence neither therefore runs in the course of the other in this respect though they share from another aspect yet the author of al nusra has judged what has a first existence by what belongs to what has a second existence and that is impossible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 0, NULL, 'Chapter Twenty-One of Part One', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'chapter twenty one of part one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 1, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 2, NULL, 'One of the clearest signs that the Soul is deficient and the First Intellect perfect is this: the First and the author of al-Islah all said that action belongs to the Second and attributed nothing to the First. Action is always a sign of deficiency and need; the absence of action is evidence of perfection and self-sufficiency. In other words, one acts only to draw a benefit or to repel a harm.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'one of the clearest signs that the soul is deficient and the first intellect perfect is this the first and the author of al islah all said that action belongs to the second and attributed nothing to the first action is always a sign of deficiency and need the absence of action is evidence of perfection and self sufficiency in other words one acts only to draw a benefit or to repel a harm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 3, NULL, 'Abu Zakariyya said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'abu zakariyya said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 4, NULL, 'The Initiator, through manipulation and tampering, would already be the Soul — and the people of religion do not hold this. All that remains, then, is the drawing of benefit or the repelling of harm; and wherever either is found, there is deficiency. In this, the Soul seeks to draw the benefit that consists in reaching the end destined for it, and so it begins to act. The Intellect, with no rank above it, is not deficient and does not move to action at all. The Soul, however, finding a station above it, remained in motion, persisting in its quest. By this reasoning we say what we say about the deficiency of the Soul and the integrity of the Intellect. The statement is clear, and praise be to God.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the initiator through manipulation and tampering would already be the soul and the people of religion do not hold this all that remains then is the drawing of benefit or the repelling of harm and wherever either is found there is deficiency in this the soul seeks to draw the benefit that consists in reaching the end destined for it and so it begins to act the intellect with no rank above it is not deficient and does not move to action at all the soul however finding a station above it remained in motion persisting in its quest by this reasoning we say what we say about the deficiency of the soul and the integrity of the intellect the statement is clear and praise be to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 5, NULL, 'The sum of what he says in this chapter is this: the Second is the agent; action serves only to draw benefit or repel harm; drawing benefit and repelling harm are marks of deficiency alone; the Intellect, being without deficiency, is still from action — its stillness arising from the fact that no rank above it remains to be sought; and the Soul, finding a rank above it, moved toward that rank to attain it.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the sum of what he says in this chapter is this the second is the agent action serves only to draw benefit or repel harm drawing benefit and repelling harm are marks of deficiency alone the intellect being without deficiency is still from action its stillness arising from the fact that no rank above it remains to be sought and the soul finding a rank above it moved toward that rank to attain it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 6, NULL, 'We say: Had the author of al-Islah been speaking of the soul as it exists in human beings, the response of the author of al-Nusra would have been the more fitting one. But his words concerned the Following that bears the name "the Soul." To invoke the condition found in human souls — that they act only to draw benefit, to repel harm, or to tamper — in order to invalidate his statement and overturn his ruling that the Following is complete and perfect: this is a manifest prejudice. For it has already been established that what is affirmed of that whose existence is a first existence — in respect of completeness and perfection — is not affirmed of that whose existence is a second existence, nor of that whose existence was once a first existence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'we say had the author of al islah been speaking of the soul as it exists in human beings the response of the author of al nusra would have been the more fitting one but his words concerned the following that bears the name the soul to invoke the condition found in human souls that they act only to draw benefit to repel harm or to tamper in order to invalidate his statement and overturn his ruling that the following is complete and perfect this is a manifest prejudice for it has already been established that what is affirmed of that whose existence is a first existence in respect of completeness and perfection is not affirmed of that whose existence is a second existence nor of that whose existence was once a first existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 7, NULL, 'The account of the author of al-Nusra on the nature of action and its divisions is not correct. Not every act aims at drawing a benefit, repelling a harm, or mere futility. An act may proceed from an agent in such a way that its benefit falls upon the object of the act rather than upon the agent from whom it issues.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the account of the author of al nusra on the nature of action and its divisions is not correct not every act aims at drawing a benefit repelling a harm or mere futility an act may proceed from an agent in such a way that its benefit falls upon the object of the act rather than upon the agent from whom it issues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 8, NULL, 'The proof of this is that heating is an act of fire, yet the act does not return to the fire; neither benefit nor harm comes back to it. The benefit and the harm fall instead upon whatever the fire''s heating reaches. The same holds for the act of the sun in illuminating the world — enabling human beings to order their affairs by their own will, allowing plants and animals and minerals to come into being through its heat. These benefits return to others, not to the sun itself; it neither gains from this act nor suffers by it. The same holds for the whales of the Sea of Oman and those others called the dolphin (الدُّلْفِين), whose nature is such that when a man is drowning in the sea, they help him escape and push him toward the shore. That act brings them no benefit and no harm; the benefit falls entirely upon the one they aid.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the proof of this is that heating is an act of fire yet the act does not return to the fire neither benefit nor harm comes back to it the benefit and the harm fall instead upon whatever the fires heating reaches the same holds for the act of the sun in illuminating the world enabling human beings to order their affairs by their own will allowing plants and animals and minerals to come into being through its heat these benefits return to others not to the sun itself it neither gains from this act nor suffers by it the same holds for the whales of the sea of oman and those others called the dolphin الدلفين whose nature is such that when a man is drowning in the sea they help him escape and push him toward the shore that act brings them no benefit and no harm the benefit falls entirely upon the one they aid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 9, NULL, 'If this is so — if it is found among natural things that do not reason, even though they are deficient in their states and dependent on others in their action — then there is nothing to deny concerning the pure, abstract, complete intellects, which were granted their perfections at the very first moment of their existence. It is fitting that they should perform acts greater than anything that appears in natural things, acts that their own perfections require of them, in proportion to the nearness of their ranks and the height of their noble degrees. These are noble acts, not for the sake of drawing benefit to themselves or repelling harm from themselves, but for the sake of others. They are acts of wisdom — not acts of drawing benefit, not of repelling harm, not of futility. Indeed, the perfect power from which the perfect, well-ordered act proceeds exists only in the perfect.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'if this is so if it is found among natural things that do not reason even though they are deficient in their states and dependent on others in their action then there is nothing to deny concerning the pure abstract complete intellects which were granted their perfections at the very first moment of their existence it is fitting that they should perform acts greater than anything that appears in natural things acts that their own perfections require of them in proportion to the nearness of their ranks and the height of their noble degrees these are noble acts not for the sake of drawing benefit to themselves or repelling harm from themselves but for the sake of others they are acts of wisdom not acts of drawing benefit not of repelling harm not of futility indeed the perfect power from which the perfect well ordered act proceeds exists only in the perfect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 10, NULL, 'Furthermore, the Following — which he called "the Soul" — is not in motion as he claimed, such that what befalls natural things would befall it. Motion of that kind belongs only to bodies, with their bodies and their natural forms. The Following stands higher in rank than natural things, though it is below the First in rank, as we made clear in the book Rahat al-Aql. By what we have set forward here, his prejudice and his argument — which do not hold for the one he is speaking of — have become plain. The statement of the author of al-Islah, that the Following is complete in completeness, stands, as we explained earlier.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'furthermore the following which he called the soul is not in motion as he claimed such that what befalls natural things would befall it motion of that kind belongs only to bodies with their bodies and their natural forms the following stands higher in rank than natural things though it is below the first in rank as we made clear in the book rahat al aql by what we have set forward here his prejudice and his argument which do not hold for the one he is speaking of have become plain the statement of the author of al islah that the following is complete in completeness stands as we explained earlier', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 11, NULL, 'It is not permissible to predicate motion and rest of what belongs to the abode of origination, namely the First and Second Intellects and the upper letters. We have already shown that motion and rest belong only to what is a body or possessed of a body. And in this there is sufficiency.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'it is not permissible to predicate motion and rest of what belongs to the abode of origination namely the first and second intellects and the upper letters we have already shown that motion and rest belong only to what is a body or possessed of a body and in this there is sufficiency', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 12, NULL, 'Chapter Twenty-Two of Part One', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'chapter twenty two of part one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 13, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 14, NULL, 'The upshot of what the author of al-Islah says is that the act of the Soul is perfected, not the essence of the Soul itself — even though with him the Soul is complete. On this view, the act of the Soul would become a soul, which is impossible with a manifest impossibility, for acts have never once been seen, in what is observed, to become agents. Consider the writer and his writing, the builder and his building: the writing does not become a writer, nor does the building become a builder. Rather, it is the man who is a writer in potency and a builder in potency who becomes a writer and a builder in actuality. We say the same of the Soul and the Intellect: the Intellect is complete in actuality; the Soul is deficient in actuality, subsisting in potency; and it comes to subsist in actuality when it gains completeness. That its act should become complete, however, is impossible.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the upshot of what the author of al islah says is that the act of the soul is perfected not the essence of the soul itself even though with him the soul is complete on this view the act of the soul would become a soul which is impossible with a manifest impossibility for acts have never once been seen in what is observed to become agents consider the writer and his writing the builder and his building the writing does not become a writer nor does the building become a builder rather it is the man who is a writer in potency and a builder in potency who becomes a writer and a builder in actuality we say the same of the soul and the intellect the intellect is complete in actuality the soul is deficient in actuality subsisting in potency and it comes to subsist in actuality when it gains completeness that its act should become complete however is impossible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 15, NULL, 'We say:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 16, NULL, 'The aim of the author of al-Islah, in saying that the act of the Soul is perfected rather than the essence of the Soul, is this: what attains the second perfection is that which comes from the Soul''s side — that which proceeds from it in the manner of what the Soul pours forth upon, issuing from potency to the measure of the act. Since the aim of his saying — that the act of the Soul is perfected — is what issues from the Soul''s overflowing, moving from potency into act and thereby attaining the second perfection; and since nothing can issue from the limit of potency into act except through what already subsists in actuality: it follows that when what subsisted in potency issues into act and attains the second perfection by acquisition, there is nothing to prevent it from resembling, in the perfection it has received, that which subsists in actuality and was granted perfection from the very first of its existence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the aim of the author of al islah in saying that the act of the soul is perfected rather than the essence of the soul is this what attains the second perfection is that which comes from the souls side that which proceeds from it in the manner of what the soul pours forth upon issuing from potency to the measure of the act since the aim of his saying that the act of the soul is perfected is what issues from the souls overflowing moving from potency into act and thereby attaining the second perfection and since nothing can issue from the limit of potency into act except through what already subsists in actuality it follows that when what subsisted in potency issues into act and attains the second perfection by acquisition there is nothing to prevent it from resembling in the perfection it has received that which subsists in actuality and was granted perfection from the very first of its existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 17, NULL, 'They share in that both subsist in actuality, even though each attained what they share not from the same side as the other. There is nothing impossible in their being alike in the respect they share; for it is well known that whatever is joined with another thing in some meaning is, in that meaning, its like.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'they share in that both subsist in actuality even though each attained what they share not from the same side as the other there is nothing impossible in their being alike in the respect they share for it is well known that whatever is joined with another thing in some meaning is in that meaning its like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 18, NULL, 'The witness to this is what our argument yields: everything that passes from the limit of potency to the limit of act subsists in actuality; everything that subsists in actuality does so by the occurrence of the second perfection to it; and therefore everything that passes from the limit of potency to act has the second perfection occur to it.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the witness to this is what our argument yields everything that passes from the limit of potency to the limit of act subsists in actuality everything that subsists in actuality does so by the occurrence of the second perfection to it and therefore everything that passes from the limit of potency to act has the second perfection occur to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 19, NULL, 'If what subsists in actuality does so by the occurrence of the second perfection to it, and what subsisted in potency and afterward came to subsist in actuality does so likewise by the occurrence of the second perfection — then they share and are alike in both having attained the second perfection, even though they differ in other respects.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'if what subsists in actuality does so by the occurrence of the second perfection to it and what subsisted in potency and afterward came to subsist in actuality does so likewise by the occurrence of the second perfection then they share and are alike in both having attained the second perfection even though they differ in other respects', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 20, NULL, 'Since what we have set forward is neither impossible nor to be denied but rather necessary, the statement of the author of al-Nusra amounts to nothing but prejudice.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'since what we have set forward is neither impossible nor to be denied but rather necessary the statement of the author of al nusra amounts to nothing but prejudice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 21, NULL, 'Chapter Twenty-Three of Part One', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'chapter twenty three of part one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 22, NULL, 'Then the author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'then the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 23, NULL, 'This is impossible with a manifest impossibility, for acts have never once been seen, in what is observed, to become agents — as shown by what he adduced from the case of the writer and the building: a proof that testifies to the very impossibility he claimed.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'this is impossible with a manifest impossibility for acts have never once been seen in what is observed to become agents as shown by what he adduced from the case of the writer and the building a proof that testifies to the very impossibility he claimed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 24, NULL, 'We say:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 25, NULL, 'Acts are, in truth, agents. The writing, which he cited as the act of the writer, is itself what converses with its reader and addresses him. Were the writing — in its forms and its tracing — not, for all that it is an act belonging to another, itself an agent upon the very soul of its reader, speaking on behalf of its author, translating him, and impressing him in its forms, the reader would never know what is in the soul of the writer. The building, in the form the builder brought into being from what was in his soul, conveys its own form to the observer through its arrangement and disposition, so that he conceives it. Were the form of the building not subsisting in actuality — capable of impressing itself upon the soul of the observer who holds its forms within him — the observer would never conceive it.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'acts are in truth agents the writing which he cited as the act of the writer is itself what converses with its reader and addresses him were the writing in its forms and its tracing not for all that it is an act belonging to another itself an agent upon the very soul of its reader speaking on behalf of its author translating him and impressing him in its forms the reader would never know what is in the soul of the writer the building in the form the builder brought into being from what was in his soul conveys its own form to the observer through its arrangement and disposition so that he conceives it were the form of the building not subsisting in actuality capable of impressing itself upon the soul of the observer who holds its forms within him the observer would never conceive it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 26, NULL, 'Likewise, the act of one who strikes — the striking itself — is the agent that produces pain in the one struck, in the manner we described in our two well-known epistles, al-Rawdah and al-Mudiah (الْمُضِيْئَة). And the word of God, exalted is He, is the most solid proof that acts are themselves agents, where He says, exalted is the Speaker:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'likewise the act of one who strikes the striking itself is the agent that produces pain in the one struck in the manner we described in our two well known epistles al rawdah and al mudiah المضييه and the word of god exalted is he is the most solid proof that acts are themselves agents where he says exalted is the speaker', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'verse', 'the soul that forgets', '3. The Soul That Forgets', 27, NULL, 'Al-Isra: 44وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ', '', 'وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ', 'Al-Isra: 44', 17, 44, 'kitab al riyad 3 the soul that forgets', 'al isra 44وان من شيء الا يسبح بحمده', 'وان من شيء الا يسبح بحمده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 28, NULL, 'There is nothing but glorifies Him with His praise. The "thing" is the act of the Maker, exalted is He, and it, together with being an act of an agent, is itself its glorification. And His saying, exalted is He:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'there is nothing but glorifies him with his praise the thing is the act of the maker exalted is he and it together with being an act of an agent is itself its glorification and his saying exalted is he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'verse', 'the soul that forgets', '3. The Soul That Forgets', 29, NULL, 'Al-Hijr: 22وَأَرْسَلْنَا ٱلرِّيَحَ لَوَقِحَ', '', 'وَأَرْسَلْنَا ٱلرِّيَحَ لَوَقِحَ', 'Al-Hijr: 22', 15, 22, 'kitab al riyad 3 the soul that forgets', 'al hijr 22وارسلنا الريح لوقح', 'وارسلنا الريح لوقح');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 30, NULL, 'And We sent the winds as fecundators. The winds are a thing, and their fecundating is His act.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'and we sent the winds as fecundators the winds are a thing and their fecundating is his act', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 31, NULL, 'With this explanation in place, the objection of the author of al-Nusra against the author of al-Islah in this chapter fails.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'with this explanation in place the objection of the author of al nusra against the author of al islah in this chapter fails', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 32, NULL, 'What the author of al-Nusra truly means when he says that acts have never been seen to become agents is this: the acts themselves have not become identical with their agents in what is observed — just as the writing has not become identical with its writer, nor the building with its builder. This, as he stated it, is a correct observation. An act does not become one and the same as that from which it issued; rather it is an agent like its own agent in respect of the action proceeding from it, even though the ranks differ and the causes vary. But the author of al-Nusra wished to take the side of the one he defends, by prejudice, against the author of al-Islah — may God sanctify their souls — and many who are associated wrong one another.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'what the author of al nusra truly means when he says that acts have never been seen to become agents is this the acts themselves have not become identical with their agents in what is observed just as the writing has not become identical with its writer nor the building with its builder this as he stated it is a correct observation an act does not become one and the same as that from which it issued rather it is an agent like its own agent in respect of the action proceeding from it even though the ranks differ and the causes vary but the author of al nusra wished to take the side of the one he defends by prejudice against the author of al islah may god sanctify their souls and many who are associated wrong one another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 33, NULL, 'Chapter Twenty-Four of Part One', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'chapter twenty four of part one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 34, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 35, NULL, 'He likened the Intellect and the Soul — in their completeness and their deficiency — to a man and to sperm, because the sperm is, in truth, the form of the man in potency and comes to stand upright like the man. Likewise the Soul is, in truth, the form of the Intellect and becomes complete like the Intellect when it receives from the Intellect the benefits destined for it. That is what he said.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'he likened the intellect and the soul in their completeness and their deficiency to a man and to sperm because the sperm is in truth the form of the man in potency and comes to stand upright like the man likewise the soul is in truth the form of the intellect and becomes complete like the intellect when it receives from the intellect the benefits destined for it that is what he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 36, NULL, 'We say:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 37, NULL, 'His claim — that sperm is in truth the form of the man in potency, and likewise that the Soul is in truth the form of the Intellect and becomes complete — is not correct. Sperm is not the form of the man, nor is the Soul, while in potency, the form of the Intellect. Sperm is matter prepared for form, empty of forms, which then acquires them under given conditions. Likewise the Soul is only a natural readiness, empty of forms, whose nature is to acquire the forms of knowable things, so that its essence is perfected through them.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'his claim that sperm is in truth the form of the man in potency and likewise that the soul is in truth the form of the intellect and becomes complete is not correct sperm is not the form of the man nor is the soul while in potency the form of the intellect sperm is matter prepared for form empty of forms which then acquires them under given conditions likewise the soul is only a natural readiness empty of forms whose nature is to acquire the forms of knowable things so that its essence is perfected through them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 38, NULL, 'Had the Soul truly been the form of the Intellect, it would follow that the Intellect must have something of which it is the form — making the form one thing and that of which it is the form another. How can this apply to what has an originated existence, in which otherness exists only by relation while the essence is one? No. This discourse, and this analogy, holds only for natural things, not for what is separate and parted from bodies.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'had the soul truly been the form of the intellect it would follow that the intellect must have something of which it is the form making the form one thing and that of which it is the form another how can this apply to what has an originated existence in which otherness exists only by relation while the essence is one no this discourse and this analogy holds only for natural things not for what is separate and parted from bodies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 39, NULL, 'Chapter Twenty-Five of Part One', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'chapter twenty five of part one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 40, NULL, 'The author of al-Nusra said:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the author of al nusra said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 41, NULL, 'Likewise, the rank of the speaker (اَلنَّاطِق) in the corporeal world is like the rank of the Intellect in the spiritual world, and the rank of the foundation (أَسَاس) is like the rank of the Following. So if it is permissible to say that the Soul is complete like the Intellect, it must equally be permissible to say that the foundation is complete like the speaker. But that is not correct, for the rank of the foundation is below the rank of the speaker — as has been made clear in the meaning of the prayer. That is what he said.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'likewise the rank of the speaker الناطق in the corporeal world is like the rank of the intellect in the spiritual world and the rank of the foundation اساس is like the rank of the following so if it is permissible to say that the soul is complete like the intellect it must equally be permissible to say that the foundation is complete like the speaker but that is not correct for the rank of the foundation is below the rank of the speaker as has been made clear in the meaning of the prayer that is what he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 42, NULL, 'We say:', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 43, NULL, 'The Second is like the First, even though in rank it is below it — just as the foundation is like the speaker, even though in rank he is below him. The Second is established in its existence, and no further degree remains for it to attain by which it might gain completeness. Likewise the foundation is complete and perfect in its own rank, with no degree left for it to ascend to that would bring it a completeness not already in its essence.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the second is like the first even though in rank it is below it just as the foundation is like the speaker even though in rank he is below him the second is established in its existence and no further degree remains for it to attain by which it might gain completeness likewise the foundation is complete and perfect in its own rank with no degree left for it to ascend to that would bring it a completeness not already in its essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 44, NULL, 'Sufficient witness to this is the act of the Prophet (صَلْعَم) and what it indicates, in that he made it obligatory to slaughter camels by nahr (النَّحْر) and to slaughter other animals by dhabh (اَلذَّبْح). The nahr is the delivering of the iron to the head of the heart (fuad) of the one slaughtered, so that whatever turbid blood is there may issue from him — corresponding to the degree of conveyance, the disclosure of secrets, and the departure of doubts and uncertainties through the ranks. The dhabh corresponds to the taking of the covenant and the release in the summons, while the one slaughtered by nahr corresponds to the foundation.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'sufficient witness to this is the act of the prophet صلعم and what it indicates in that he made it obligatory to slaughter camels by nahr النحر and to slaughter other animals by dhabh الذبح the nahr is the delivering of the iron to the head of the heart fuad of the one slaughtered so that whatever turbid blood is there may issue from him corresponding to the degree of conveyance the disclosure of secrets and the departure of doubts and uncertainties through the ranks the dhabh corresponds to the taking of the covenant and the release in the summons while the one slaughtered by nahr corresponds to the foundation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 45, NULL, 'It is as though the Prophet (صَلْعَم), in making this act manifest, informed the community that followed him, on the one side, and the imams of his cycle: that he did not place the foundation in his own station within the summons to the inner call — which is the completion of the worship of God that leads to the affirmation of God''s oneness and the knowledge of His bounds — until he had taught him what holds his perfection and disclosed to him what holds his completeness. Thus he raised the foundation''s degree through conveyance, and the foundation''s path to perfection and completion is unlike the path of any other member of the Prophet''s community — the path by which each of them obtains from him the conveyance and the completeness.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'it is as though the prophet صلعم in making this act manifest informed the community that followed him on the one side and the imams of his cycle that he did not place the foundation in his own station within the summons to the inner call which is the completion of the worship of god that leads to the affirmation of gods oneness and the knowledge of his bounds until he had taught him what holds his perfection and disclosed to him what holds his completeness thus he raised the foundations degree through conveyance and the foundations path to perfection and completion is unlike the path of any other member of the prophets community the path by which each of them obtains from him the conveyance and the completeness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 46, NULL, 'The conveyance and the covenant were the last things I set down, and the prayer itself bears witness to the order in which they fall. The Prophet did not take the covenant from the sons of the call first and then disclose to them the degree of perfection out of any contradiction. The conveyance serves only to point and indicate: it shows that the natural souls, which stand below the Second, begin in potency and then emerge by acquisition into act at the last — which is their perfection and their completion — so that each may believe of it what is fitting to believe. Nor did the matter rest at this single indication. He indicated the Follower''s completion from another side as well, in the two units of the dawn prayer, which stand upon the First and the Second. In the first unit, which stands upon the First, he made it obligatory to recite the glorification, the praise, and the sura. In the second unit he made obligatory the recitation of the Qunut in place of the glorification that belongs to the first, so that the second might stand in the same state as the first from the side of perfection. Their distinction lies only in rank within existence: the first is the beginning of existence, like the first unit, and the second is the second of existence, like the second unit.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the conveyance and the covenant were the last things i set down and the prayer itself bears witness to the order in which they fall the prophet did not take the covenant from the sons of the call first and then disclose to them the degree of perfection out of any contradiction the conveyance serves only to point and indicate it shows that the natural souls which stand below the second begin in potency and then emerge by acquisition into act at the last which is their perfection and their completion so that each may believe of it what is fitting to believe nor did the matter rest at this single indication he indicated the followers completion from another side as well in the two units of the dawn prayer which stand upon the first and the second in the first unit which stands upon the first he made it obligatory to recite the glorification the praise and the sura in the second unit he made obligatory the recitation of the qunut in place of the glorification that belongs to the first so that the second might stand in the same state as the first from the side of perfection their distinction lies only in rank within existence the first is the beginning of existence like the first unit and the second is the second of existence like the second unit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 47, NULL, 'The twenty-sixth chapter of Part One. And we say, in answer to his claim that if it were permitted to call the soul as perfect as the Intellect, it would equally be permitted to call the Foundation like the Speaker, and that this is not right: how could it not be right, when the Foundation is the one who stands in the place of the Prophet and his family? Were he to fall short of standing in that place, or were he not sufficient, complete, and perfect as the Prophet is, God would not have enjoined obedience to him. How would God the Exalted enjoin obedience to one who is like others in deficiency? Neither of these can stand. Nor does wisdom permit — given that the Messenger is a messenger to all who are of his time and all who are born after him, and a proof upon His creation — that the community be left without one who is like the Messenger, so that no one among them is as he is and the proof stands established against them. The Foundation, then, is like the Speaker who comes after him in one respect, and unlike the Speaker in another. It is proof enough that the disparity between them is in rank and not in essence that the author himself argues by rank alone, saying the rank of the Foundation is below the rank of the Speaker — for he could argue by nothing except rank. It is clear from what we have set out that the position of the author of al-Islah has withstood the objection of the author of al-Nusra, and that his saying that the Second is deficient — though it is the saying of the author of al-Nusra — holds only in the sense in which it must rightly be said.', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the twenty sixth chapter of part one and we say in answer to his claim that if it were permitted to call the soul as perfect as the intellect it would equally be permitted to call the foundation like the speaker and that this is not right how could it not be right when the foundation is the one who stands in the place of the prophet and his family were he to fall short of standing in that place or were he not sufficient complete and perfect as the prophet is god would not have enjoined obedience to him how would god the exalted enjoin obedience to one who is like others in deficiency neither of these can stand nor does wisdom permit given that the messenger is a messenger to all who are of his time and all who are born after him and a proof upon his creation that the community be left without one who is like the messenger so that no one among them is as he is and the proof stands established against them the foundation then is like the speaker who comes after him in one respect and unlike the speaker in another it is proof enough that the disparity between them is in rank and not in essence that the author himself argues by rank alone saying the rank of the foundation is below the rank of the speaker for he could argue by nothing except rank it is clear from what we have set out that the position of the author of al islah has withstood the objection of the author of al nusra and that his saying that the second is deficient though it is the saying of the author of al nusra holds only in the sense in which it must rightly be said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 48, NULL, 'The twenty-seventh chapter of Part One. The author of al-Nusra argued that bowing is upon the Foundation and prostration upon the Speaker, and that the supplication in bowing,', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'the twenty seventh chapter of part one the author of al nusra argued that bowing is upon the foundation and prostration upon the speaker and that the supplication in bowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 49, NULL, 'Sayingسُبْحَانَ رَبِّي الْعَظِيمِ وَبِحَمْدِهِ"Glory be to my Lord the Great, and praise be to Him,"', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'sayingسبحان ربي العظيم وبحمده glory be to my lord the great and praise be to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 50, NULL, 'is the purification of the fashioned one from the side of his greatest Cultivator, who is the Follower; while the supplication in prostration,', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'is the purification of the fashioned one from the side of his greatest cultivator who is the follower while the supplication in prostration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 51, NULL, 'Sayingسُبْحَانَ رَبِّي الْأَعْلَى وَبِحَمْدِهِ"Glory be to my Lord the Most High, and praise be to Him,"', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'sayingسبحان ربي الاعلي وبحمده glory be to my lord the most high and praise be to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 52, NULL, 'is the purification of the Speaker from the side of his Cultivator, who is the Second — the Higher being upon the Prior, since his highest Cultivator is upon the Prior. He said that the Speaker (ع) mentioned this meaning in the revelation, in His saying,', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'is the purification of the speaker from the side of his cultivator who is the second the higher being upon the prior since his highest cultivator is upon the prior he said that the speaker ع mentioned this meaning in the revelation in his saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 53, NULL, 'An-Najm: 8ثُمَّ دَنَا فَتَدَلَّىٰ"Then he drew near and came down,"', '', NULL, 'An-Najm: 8', NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'an najm 8ثم دنا فتدلي then he drew near and came down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 54, NULL, 'meaning that the Speaker drew near to standing upon the rank of the Intellect, so that the Foundation hung down from him, and he was', '', NULL, NULL, NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'meaning that the speaker drew near to standing upon the rank of the intellect so that the foundation hung down from him and he was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('kitab-al-riyad', 'chapter', 'the soul that forgets', '3. The Soul That Forgets', 55, NULL, 'Sayingقَابَ قَوْسَيْنِ"the measure of two bows,"', '', NULL, 'Saying', NULL, NULL, 'kitab al riyad 3 the soul that forgets', 'sayingقاب قوسين the measure of two bows', '');
